(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zu"] = {"ui":{"skip":"Yeqela ukuya okuqukethwe","back":"← Buyela ku-AI-gile","lang.button":"Ulimi: {name}","lang.dialog":"Khetha ulimi","lang.search":"Sesha izilimi","lang.none":"Alukho ulimi oluhambisanayo","lang.notYet":"{name} alukahunyushwa okwamanje","theme.aria":"Shintsha itimu: ekhanyayo, emnyama noma emnyama bhuqe","theme.toLight":"Shintshela etimini ekhanyayo","theme.toDark":"Shintshela etimini emnyama","theme.toBlack":"Shintshela etimini emnyama bhuqe (emnyama ngempela, ilungele izikrini ze-OLED)","words.underline":"Dweba umugqa ngaphansi kwalawa magama ekhasini","words.underlineHelp":"Beka i-mouse phezu kwegama elinamachashazi noma ulithinte ukuze ubone ukuthi lisho ukuthini.","words.col.todo":"Amakhadi akhethelwe okwamanje: iqembu lizoqala ngawo olandelayo.","words.col.doing":"I-AI isebenza kule khadi manje.","words.col.review":"I-AI eyodwa isiqedile umsebenzi; enye iyawuhlola ngaphambi kokuba ufike kuwe.","words.col.verify":"Kulinde wena: yizame bese uthi uyasebenza yini.","words.col.team":"Amanothi noma izimpendulo zakho, zilinde iqembu ukuba lizithathe.","words.col.done":"Kuqediwe futhi kwamukelwe.","index.title":"AI-gile: iqembu lakho le-AI lokuthuthukisa, ebhodini elilodwa","index.description":"I-AI-gile yibhodi le-kanban lamaqembu e-AI abhala ikhodi. Asebenza ngenkathi ulele; wena uthola inqwaba emfushane yezinto zokuthatha isinqumo, ukuhlola nokwamukela.","hero.logoAlt":"Isithonjana sebhodi le-AI-gile","hero.h1.html":"Iqembu lakho le-AI lokuthuthukisa, ebhodini&nbsp;elilodwa.","hero.alpha":"🐣 I-pre-alpha evaliwe","hero.alphaTitle":"Kusenesikhathi futhi akukaqedwa: siyabonga ngokuzama!","hero.lede":"Akha ngenkathi ulele. Uvuka kunqwaba emfushane eyodwa: imibuzo embalwa, izinto ezimbalwa zokuhlola, idayimane elilodwa noma amabili ansomi. Chofoza, yamukela, ubuyele ekhofini lakho.","dl.windows":"Uhlelo lwe-Windows","dl.browser":"Lusebenzise kusiphequluli sakho","dl.messenger":"📱 I-Messenger yefoni yakho","dl.soon":"Kuyeza maduze","dl.notify":"🔔 Ngazise lapho livulwa","dl.notifySmall":"I-alpha noma i-beta","hero.secondary":"I-agile, kodwa iqembu alidingi ikhofi le-stand-up. (Nokho liyazenza ama-stand-up.)","pitch.h2":"I-AI-gile ngamagama amaningi noma amancane njengoba ufuna","pitch.lede":"Khetha ubude, kusukela egameni elilodwa kuya kwangu-144. Ubude ngabunye buyincazelo yabo, ebhalelwe leso silinganiso. Donsa isilayidi noma sebenzisa imicibisholo.","pitch.rangeLabel":"Ubude ngamagama","pitch.dice":"🎲 enye inguqulo","pitch.words.one":"igama elingu-{n}","pitch.words.other":"amagama angu-{n}","pitch.letters.one":"uhlamvu olungu-{n}","pitch.letters.other":"izinhlamvu ezingu-{n}","pitch.chars.one":"uhlamvu olungu-{n}","pitch.chars.other":"izinhlamvu ezingu-{n}","count.line.html.one":"ikhadi elingu-{n} ebhodini khona manje","count.line.html.other":"amakhadi angu-{n} ebhodini khona manje","people.humans.html.one":"👥 umuntu ongu-{n}","people.humans.html.other":"👥 abantu abangu-{n}","people.agents.html.one":"🤖 i-ejenti engu-{n}","people.agents.html.other":"🤖 ama-ejenti angu-{n}","people.working.html.one":"⚡ {n} basebenza khona manje","people.working.html.other":"⚡ {n} basebenza khona manje","pre.title":"AI-gile: kukhona okwakhiwayo","pre.description":"Kukhona okwakhiwayo lapha: ibhodi lapho amaqembu e-AI akha lokho okucelayo, futhi akufundise ngesikhathi esebenza. Okwamanje yi-pre-alpha evaliwe nabangani.","pre.h1":"Kukhona okwakhiwayo lapha. 🤫","pre.line":"Ibhodi lapho amaqembu e-AI akha lokho okucelayo, futhi akufundise ngesikhathi esebenza. Okwamanje yi-pre-alpha evaliwe nabangani.","pre.btn":"🔔 Ngazise lapho livulwa","pre.peek":"Ngemuva kwengilazi: ibhodi langempela, bukhoma. Ikhadi ngalinye liwumugqa onombala.","pre.peekFake":"Ngemuva kwengilazi: libukeka kanje ibhodi elisebenzayo.","pre.night":"🌙 Umlindi wasebusuku nguye obhekele · 😴 umuntu uyaphumula","features.aria":"Okwenzayo","f.pile.h":"Inqwaba eyodwa yakho","f.pile.html":"<b>Kuwe</b> iqoqe konke okukulindele kuwo wonke amaphrojekthi: imibuzo, izinto zokuhlola, imisebenzi umuntu kuphela ayenzayo. Ulayini wakho ukutshela ukuthi yini elandelayo nokuthi kuthatha isikhathi esingakanani.","f.sleep.h":"Amaqembu asebenza ulele","f.sleep.p":"Iphrojekthi ngayinye inomholi neqembu lama-ejenti e-AI. Phawula ekhadini futhi iqembu liyavuka, lenze umsebenzi, liwubuyisele nezinyathelo umuntu ozikhathele angazilandela.","f.tester.h":"Umhloli we-AI uhlola kuqala","f.tester.p":"Ngaphambi kokuba kukufinyelele, umhloli ulandela izinyathelo kukhophi yohlelo bese ekukhombisa ayekubonile, ngesithombe-skrini. Hlola ngokushesha okwedlulile bese wamukela ngokuchofoza kanye.","f.proof.h":"Ubufakazi, hhayi izithembiso","f.proof.p":"Ukudluliselwa ngakunye kukhombisa okushintshile: amafayela, umahluko, izithombe-skrini. Akudingeki uvule uhlelo ngalunye ukuze ubone ukuthi sekuphelile yini.","f.chat.h":"Xoxa nabaholi bakho","f.chat.p":"Umugqa ofana nowe-Discord: isithonjana esisodwa kuphrojekthi ngayinye, amadayimane ansomi kokudinga wena. Thumela umholi umbono; bayiguqulela emakhadini nasepulanini, nenkinobho ethi ✅ Qala.","f.tidy.h":"Iziqoqa ngokwayo","f.tidy.p":"Amakhadi ahlobene ayahlangana abe linye, izihloko ezididayo ziyalungiswa, futhi ukuhlolwa kwamathokheni kugcina ikhodi incane. Izinto ezimbalwa zokushintsha phakathi kwazo, okuncane ongacabanga ngakho.","f.private.h":"Kungokwakho, ekhompyutheni yakho","f.private.li1":"Ibhodi lisebenza emshinini wakho futhi lilandela wena kuphela.","f.private.li2":"Imilayezo eyimfihlo phakathi kwabantu ibethelwe isuka ekugcineni iye ekugcineni.","f.private.li3":"Awekho ama-akhawunti, awekho ama-tracker, awekho amakhukhi.","f.lang.h":"Ngolimi lwakho","f.lang.p":"Izilimi ezingaphezu kwekhulu namashumi amabili, kusukela esiDashi, isiWelsh nesiJapane kuya umphangi wasolwandle, isiYoda nesiKlingon, nokushintsha ngokushesha kubuyele esiNgisini emagameni ochwepheshe.","f.service.h":"Kusuka embonweni kuya kusevisi yangempela","f.service.p":"Wakhe okuthile nge-AI manje abantu sebekusebenzisa? Kumake njengesevisi futhi ibhodi likusiza ukuyiqhuba kahle: ukuhlola i-uptime, ikhasi lesimo lomphakathi, izigameko ezinokuhlaziywa okubhaliwe, izinguquko ezidinga u-Hamba, izipele ezihlolwa nsuku zonke. Usizo lufundisa isinyathelo ngasinye njengoba uqhubeka.","msgr.h2":"AI-gile Messenger: ithimba lakho ephaketheni lakho","msgr.p1":"Khuluma nethimba lakho le-AI ngaphandle kokuvula ibhodi. Xoxa nabaholi bamaphrojekthi akho nabangane bakho, ubone izinyathelo zokuhlola zekhadi futhi uziphendule, konke ngefoni yakho.","msgr.p2":"Ukuze uyixhume, skena ikhodi ye-QR ebhodini lakho. Okokuqala? Ingxoxo yedemo enobungane izokubonisa konke.","msgr.when":"I-Android kuqala, bese kuba inguqulo yewebhu yamafoni ne-iPhone.","msgr.who":"Umholi wephrojekthi yakho","msgr.b1":"Ukulungiswa kwemodi emnyama sekulungile. Ufuna izinyathelo zokuhlola?","msgr.b2":"Yebo ngiyacela!","msgr.b3":"1. Vula Izilungiselelo. 2. Khetha Okumnyama. Kubukeka kulungile?","tl.aria":"Isikhathi esisukela engxoxweni yokuqala kuya emgwaqweni wesikhathi esizayo","tl.h2":"Kusukela engxoxweni yokuqala kuya kokulandelayo","tl.lede":"Amadethi nezikhathi zangempela, ngesikhathi sendawo yakho. Ngemva kwanamuhla kuyisu, akukho madethi aqinisekisiwe.","tl.today":"Namuhla","tl.planned":"kuhlelwe","tl.doing":"kuyaqhubeka","tl.cards.one":"ikhadi elingu-{n}","tl.cards.other":"amakhadi angu-{n}","join.h2":"Joyina","join.lede":"I-AI-gile yakhiwa umuntu oyinqaba onentshebe, one-AuDHD nezimpi ezimbalwa nempilo yengqondo, kanye nenqwaba yama-ejenti anesineke. Okwamanje iyimfihlo, kuyi-alpha evaliwe nabangani. Ungathanda ukuzama lapho ivuleka?","join.btn":"Bhalisa isithakazelo","join.small":"Sizokubhalela nge-imeyili, akukho okunye","footer.tag":"I-AI-gile. Awekho ama-tracker, awekho amakhukhi, awekho ikhofi le-stand-up.","footer.licence":"Ilayisense yebhizinisi","footer.status":"Isimo","footer.privacy":"Esikugcinayo","footer.thanks":"Amakholi ngenxa ye-ChilledChat","form.sending":"Iyathumela…","form.failed":"Akusebenzanga: zama futhi emuva kwesikhathi.","form.offline":"Asikwazanga ukufinyelela ku-AI-gile: zama futhi emuva kwesikhathi.","form.keep":"Sikusebenzisela kuphela ukukuphendula, bese sikususa. Awekho ama-tracker, awekho amakhukhi.","form.keepLink":"Esikugcinayo","interest.title":"I-AI-gile: ngazise lapho i-alpha ivulwa","interest.description":"Shiya i-imeyili yakho ukuze uzwe lapho i-alpha noma i-beta evaliwe ye-AI-gile ivulwa.","interest.h1":"🔔 Ngazise lapho livulwa","interest.lede":"I-AI-gile iku-pre-alpha evaliwe. Shiya i-imeyili yakho futhi sizobhala kanye kuphela, lapho kunendawo yakho.","interest.email":"I-imeyili yakho","interest.which":"Ukuhlolwa kuphi?","interest.alpha":"I-alpha evaliwe: ekuqaleni, ayikaphelele, ushintsho oluningi","interest.beta":"I-beta: iqinile kakhulu, kamuva","interest.both":"Noma iyiphi, nanoma iyiphi eza kuqala","interest.submit":"Ngifake ohlwini","interest.thanks":"Siyabonga! Usohlwini.","licence.title":"I-AI-gile: ilayisense yebhizinisi","licence.description":"Usebenzisa i-AI-gile ebhizinisini lakho? Faka isicelo selayisense yebhizinisi mahhala.","licence.h1":"📜 Ilayisense yebhizinisi","licence.lede":"Usebenzisa i-AI-gile emsebenzini? Sitshele ukuthi ungubani nokuthi wenzani. Uma kwenza okuhle, ilayisense ayibizi lutho.","licence.company":"Inkampani","licence.website":"Iwebhusayithi","licence.what":"Okwenzayo","licence.how":"Ikusiza kanjani umhlaba","licence.email":"I-imeyili","licence.submit":"Faka isicelo","licence.thanks":"Siyabonga! Sizophendula nge-imeyili.","status.title":"Isimo se-AI-gile","status.h1":"Isimo se-AI-gile","status.quiet":"Konke kuthule","status.intro":"Ingabe i-AI-gile iyasebenza manje? Leli khasi lihlola iwebhusayithi, ukwabelana ngamabhodi, izingcingo nokulanda njalo ngemizuzu engu-5.","status.up":"Iyasebenza (iphendule ngo-{ms} ms)","status.slow":"Ayiphendulanga ekuhloleni kokugcina, iyazama futhi","status.down":"Ayisebenzi: ayiphendulanga ekuhloleni okubili kokugcina","status.svc.web":"Iwebhusayithi","status.svc.web.offers":"Le sayithi: ukuthi iyini i-AI-gile, nefomu elithi ngazise","status.svc.boards":"Ukwabelana ngamabhodi","status.svc.boards.offers":"Amabhodi omphakathi, imilayezo phakathi kwabangane nezimemo","status.svc.calls":"Izingcingo","status.svc.calls.offers":"Izwi, ividiyo nokwabelana ngesikrini ku-AI-gile","status.svc.download":"Ukulanda","status.svc.download.offers":"Isifaki se-Windows nezixhumanisi zezimemo","status.checking":"Iyahlola…","status.offline":"Asikwazi ukufinyelela insizakalo yesimo okwamanje (iyazama futhi)","status.updated":"ibuyekezwe {ago}","status.justNow":"khona manje","status.min":"imizuzu engu-{n} edlule","status.hours":"amahora angu-{n} edlule","status.days":"izinsuku ezingu-{n} edlule","privacy.title":"I-AI-gile: esikugcinayo","privacy.h1":"Esikugcinayo","privacy.lede":"Ngamafuphi: kuphela lokho osithumelela kona, futhi hhayi isikhathi eside.","privacy.only":"Kuphela lokho osithumelela kona: lokho okubhala efomini, njenge-imeyili yakho. Akukho okunye ngawe.","privacy.sealed":"Kuvalwa ngophawu ukuze iseva yethu ingakwazi ukukufunda: kusesiphequluli sakho ngaphambi kokuthi kuhambe (esipheqululini esidala, ngokushesha nje uma kufika). Yibhodi lethu kuphela elingakuvula.","privacy.server":"Kususwa kuseva ngokushesha nje uma kufika ebhodini lethu. Noma yini esekhona ngemva kwezinsuku ezingu-30 iyasuswa noma kunjalo.","privacy.board":"Sikugcina ebhodini lethu kuze kube yilapho sesikuphendulile, bese sikususa nalapho.","privacy.none":"Awekho ama-tracker, awekho amakhukhi, akukho ukuhlaziywa.","privacy.local":"Ulimi lwakho nokukhetha kwakho ukukhanya noma ubumnyama kuhlala esipheqululini sakho. Akukaze kuthunyelwe kithi.","privacy.ask":"Ufuna kususwe ngokushesha? Phendula i-imeyili yethu usitshele.","live.h2":"Bukela ngenkathi yakhiwa, bukhoma","live.caption":"Wonke ikhadi lifihliwe: ubona isimo somsebenzi, hhayi amagama.","live.watching.one":"bukhoma: {n} uyabuka","live.watching.other":"bukhoma: {n} bayabuka","live.last.now":"Ikhadi lokugcina lihanjiswe nje manje","live.last.min.one":"Ikhadi lokugcina lihanjiswe umzuzu ongu-{n} owedlule","live.last.min.other":"Ikhadi lokugcina lihanjiswe imizuzu engu-{n} edlule","live.last.hour.one":"Ikhadi lokugcina lihanjiswe ihora elingu-{n} eledlule","live.last.hour.other":"Ikhadi lokugcina lihanjiswe amahora angu-{n} edlule","live.last.day.one":"Ikhadi lokugcina lihanjiswe usuku olungu-{n} olwedlule","live.last.day.other":"Ikhadi lokugcina lihanjiswe izinsuku ezingu-{n} ezedlule","live.offline":"Ibhodi elibukhoma lithatha ikhefu elifushane. Buya maduze.","live.cols":"Backlog|Okufanele kwenziwe|Kuyaqhubeka|Iqembu liyahlola|Kuwe ukuthi test|Kweqembu|Kuphelile","footer.models":"I-AI-gile ikusebenzisela amamodeli e-AI. Lokho abakushoyo nabakwenzayo kungokwabo, ngakho hlola ngaphambi kokukholwa.","privacy.ai.h":"Ingxenye ye-AI","privacy.ai.models":"I-AI-gile yibhodi. Umsebenzi wenziwa amamodeli e-AI avela kwamanye amakhampani, njenge-Claude, Codex ne-Gemini, ku-akhawunti zakho.","privacy.ai.check":"Lokho abakubhalayo nabakwenzayo kuvela kubo, futhi kungase kube okungalungile. Hlola ngaphambi kokukuthembela noma kokukukhipha.","privacy.ai.files":"Bashintsha amafayela futhi basebenzise imiyalo kumafolda owaxhumayo. Gcina isipele.","privacy.ai.send":"Lokho okunika imodeli kuya enkampanini eyisebenzisayo, ngaphansi kwemigomo yayo. Imigomo nezindleko zenkampani ngayinye ziyasebenza.","privacy.ai.asis":"I-AI-gile iyinguqulo yokuhlola yokuqala, inikezwa njengoba injalo."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Amarobhothi.","Nikeza."]},{"n":2,"texts":["Kanban yamarobhothi.","Ama-ejenti, ahlelekile.","Imibono, yakhiwe."]},{"n":3,"texts":["Ibhodi lamarobhothi lamahhala.","Imibono iba izici.","Kanban yama-ejenti, mahhala."]},{"n":5,"texts":["Ibhodi eliqhutshwa ngama-ejenti, lamahhala nje.","Wena ubhala amakhadi. Ama-ejenti akha.","Mahhala, ekhaya, ihloliwe, nenhlanhla encane."]},{"n":8,"texts":["Ibhodi le-kanban lamahhala lapho ama-ejenti e-AI asebenza khona.","Bhala umbono. Ama-ejenti awakhe. Wena uyawamukela.","I-agile yomuntu oyedwa namarobhothi amaningi anesineke nje."]},{"n":13,"texts":["Ibhodi le-kanban ekhompyutheni yakho lapho ama-ejenti e-AI athatha khona amakhadi.","Bhala umbono wakho. Iqembu lama-ejenti liyawakha lapho. Bese umhloli we-AI uyawuhlola ngemva kwalokho.","Mahhala, awekho ama-akhawunti, awekho ama-tracker: ibhodi, amarobhothi athile, wena nguwe oyinhloko."]},{"n":21,"texts":["I-AI-gile yibhodi le-kanban lokusebenza nama-ejenti e-AI abhala ikhodi. Wona athatha amakhadi bese wena uwahlola futhi uwamukele ngokwakho lapho eseqedile.","Iphrojekthi ngayinye ithola umholi kanye neqembu lama-ejenti e-AI. Phawula noma yiliphi ikhadi, bese iqembu liyavuka liqale ukusebenza ngokushesha okukhulu.","Yibhodi lemisebenzi yomuntu siqu, lamahhala, elisebenza ekhompyutheni yakho uqobo. Abasebenzi bangamarobhothi nje. Futhi ophendula ngokuthi yebo nguwe wedwa."]},{"n":34,"texts":["Ubeka imibono yakho ebhodini. Iqembu lama-ejenti e-AI liyiguqula ibe yizici ezisebenzayo, liyazihlola, bese liziletha kuwe nezinyathelo zokuzama. Akukho okubalwa njengokuphelile ngaphandle kokuthi wena uthi kunjalo. Konke kwenzeka ekhompyutheni yakho.","I-AI-gile yibhodi le-kanban elenziwe ekhaya, elakhiwa nguRich ngosizo olukhulu lwama-ejenti manje alawulwa yilo. Lamahhala, lisebenza ekhompyutheni yakho, futhi labelwana nabangani, alithengiswa muntu. Lakhelwe ukusiza nokujabulisa, akukho okunye okufihliwe nhlobo.","Cabanga ibhodi le-kanban elijwayelekile, namakholomu asuka ku-Backlog aze afike ku-Done, kodwa amakhadi athathwa ama-ejenti e-AI. Abika inqubekela phambili, abuza lapho ebambekile, futhi njalo alinde ukuvuma kwakho, uthi yebo noma cha."]},{"n":55,"texts":["I-AI-gile yibhodi le-kanban lapho iqembu lakhiwe ngama-ejenti e-AI. Iphrojekthi ngayinye inomholi ohlela umsebenzi, nabasizi abawakhayo. Uma isici sesilungile, umhloli we-AI uyasizama, athathe nesithombe-skrini, bese sifika enqwabeni yakho. Ungasamukela, noma uphawule bese iqembu liqala kabusha ukusebenza ngokukhulu ukunaka. Konke kulula futhi kucacile, ngakho ungabuyela ekhofini lakho.","Laqala njengendlela yomuntu oyedwa yokulandelela izikhathi eziningi zokubhala ikhodi nge-AI ngasikhathi sinye, laze lakhula laba yibhodi langempela. Lisebenza emshinini wakho, alidingi i-akhawunti, futhi alinawo ama-tracker. Lamahhala kubangani nakuwo wonke onelukuluku. Alikaphelele, ngakho lindela ubukhali obuthile nezimanga ezimbalwa ngezikhathi ezithile. Kungcono ukuqala kancane, kanjalo siyakhula ndawonye nabangani.","Nanku iqiniso eliqinile. Kusadingeka ube nemibono yakho, futhi kusadingeka uhlole imiphumela ngokwakho. I-AI-gile yenza konke okuphakathi: igcina amakhadi ehleleke kahle, ivusa i-ejenti efanele uma uphawula, ikhombisa ncamashi okushintshile, futhi ikubeka konke enqwabeni eyodwa emfushane eyakho kuphela. Ukucabanga nokukhetha kusalokhu kungokwakho, futhi lokho kunjalo ngenhloso."]},{"n":89,"texts":["I-AI-gile yibhodi le-kanban lamahhala olisebenzisa ekhompyutheni yakho uqobo. Esikhundleni sabantu, iphrojekthi ngayinye inalo iqembu lama-ejenti e-AI: umholi oguqula imibono yakho ibe amakhadi nepulani, nabasizi abathatha amakhadi ngokulandelana kokubaluleka. Uma okuthile sekwakhiwe, umhloli we-AI ulandela izinyathelo zokuhlola bese ekukhombisa lokho akubonile ngesithombe-skrini. Bese kulinda enqwabeni eyodwa ethi Kuwe. Uyakwamukela, noma uphawule bese iqembu lizama futhi kusukela ekuqaleni. Akukho nakanye okufika ku-Done ngaphandle kwakho wena. Wonke umsebenzi wenzeka ekhompyutheni yakho, futhi awudingi i-akhawunti ukuze uwusebenzise.","Ezinye izici ongase ungazilindele. Umqaphi wasebusuku ugcina ikholomu ethi To do igcwele ngenkathi ulele, ekhetha amakhadi angadingi mpendulo evela kuwe. Isibali samathokheni sikhombisa ukuthi ama-ejenti asebenzise malini namuhla nalesi sonto, futhi imodi ethi No Token Mode iwatshela ukuba ayeke ukusebenzisa. Ungathumela imilayezo kubangani, futhi imilayezo eyimfihlo ibethelwe ngokuphelele. Ibhodi likhuluma izilimi ezingaba ngu-120, kubandakanya isiDashi, isiFlemish, umphangi wasolwandle nesiKlingon. Akukho kulokhu okubiza lutho, futhi akekho ozama ukukudayisela lona. Konke lokhu kwenzelwe ukuba ulale kahle, wazi ukuthi umsebenzi uqhubeka.","I-AI-gile iyiphrojekthi encane, yomuntu siqu, hhayi inkampani. URich wayefuna ukunakekela amaphrojekthi amaningi e-AI ngaphandle kokuvula uhlelo ngalunye ukuze alihlole, ngakho yena nama-ejenti akha ibhodi, base besebenzisa lona ibhodi ukwakha okusele kwalo uqobo. Iku-pre-alpha evaliwe, okusho ukuthi isebenza, ikakhulukazi, kwabangani abambalwa kuphela. Alikho ikhasi lamanani, alikho ileta yezindaba, futhi alikho icebo lokukhula. Uma lizwakala linomsebenzi kuwe, ungacela ukulizama lapho livuleka kancane nje. Uma ufuna ukuzama, bhala nje ukucela, bese sikuphendula ngokushesha uma sesikulungele kahle."]},{"n":144,"texts":["I-AI-gile yibhodi le-kanban lomuntu oyedwa nama-ejenti amaningi e-AI. Lisebenza ekhompyutheni yakho uqobo futhi lamahhala ngokuphelele. Wengeza amaphrojekthi, futhi iphrojekthi ngayinye ithola umholi neqembu elincane. Uxoxa nomholi, kufana kakhulu ne-Discord, uchaze umbono wakho; umholi uwuguqulela emakhadini nasepulanini, bese elinda ukuthi ucindezele u-Qala. Iqembu lisebenza ngamakhadi ngokulandelana kokubaluleka, lisebenzisa umugqa wemiyalo olula owenzelwe amamodeli olimi. Ngaphambi kokuba kukubuyele, umhloli we-AI ulandela izinyathelo kukhophi yohlelo bese enamathisela isithombe-skrini. Umsebenzi oqediwe uwela enqwabeni yakho kanye namafayela ashintshile nomahluko wawo. Uyawamukela, noma ushiye isikhumbuzo bese iqembu livuka lizame futhi. Wena kuphela ongashintshela ikhadi ku-Done, akekho omunye. Konke okwenziwayo kuyabonakala, ngakho awudingi ukuthemba ngokungaboni. Ibhodi lilula, linesineke, futhi lihlala lilinde izinqumo zakho ngokuthula okukhulu. Kuphelele kumuntu ofuna ukunyakazisa umsebenzi ngaphandle kokuhlala kuwo usuku lonke.","Usuku ne-AI-gile, kafushane. Kusihlwa uphawula amazwana ambalwa: le nkinobho isendaweni engafanele, lolo hlu kufanele luhlelwe, ingabe singaba nemodi emnyama yini. Uyalala. Ama-ejenti afunda amazwana, enze izinguquko, azihlole, bese ezibuyisela kuwe. Uma ikholomu ethi To do iphela, umqaphi wasebusuku uyigcwalisa evela ku-backlog ngamakhadi angadingi mpendulo evela kuwe. Ekuseni kunenqwaba eyodwa emfushane: imibuzo embalwa nezinto ezimbalwa zokuzama, ngayinye inezinyathelo umuntu onokulala angazilandela kanye nesithombe-skrini sokuthi isebenza. Uchofoza ngazo ngayinye, wamukele ezinhle bese uthumela ezisele emuva ukuze zilungiswe. Isibali samathokheni sikhombisa ukuthi konke kusebenzise malini, futhi imodi ethi No Token Mode ikhona ezinsukwini zokonga. Bese udla ibhulakufesi, okungakasizi ngakho ama-ejenti. Ngesonto elilandelayo ungenza okufanayo, uphinde ubone ukuthi kuthatha isikhathi esingakanani. Awudingi ukuhlala usuku lonke ubheke isikrini, futhi ibhodi lihlala lilungele wena.","Okokuqala, ukuthi i-AI-gile ayiyona yini. Akuyona inkampani entsha, akuthengiswa, futhi akekho oqoqa idatha yakho. Yibhodi lamahhala elisebenza ekhompyutheni yakho, ngaphandle kwama-akhawunti, ngaphandle kwama-tracker nangaphandle kwamakhukhi. Yini yona: indawo eyodwa ehlelekile yokubona wonke amaphrojekthi e-AI ngasikhathi sinye, neqembu lama-ejenti enza amakhadi nawe uthatha izinqumo. Ihlanganisa amakhadi ahlobene, ilungisa izihloko ezididayo, futhi ibheka ukuthi ikhodi ihlala incane kangakanani. Ikhuluma izilimi ezingaba ngu-120, kusukela esiDashi nesiFlemish kuya kumphangi wasolwandle nesiKlingon. Abangani bangathumelana imilayezo, ngasese futhi ibethelwe. Yakhiwe nguRich nenqwaba yama-ejenti anesineke, ikakhulukazi isebenzisa yona ngokwayo. Iku-pre-alpha evaliwe, ngakho inobukhali kwezinye izindawo. Uma kuzwakala kumnandi, cela kahle futhi ungangena kusenesikhathi. Kuyibhodi elincane elinenhliziyo, elenzelwe ukuba lisize abantu abangenaso isikhathi sokuhlola konke ngabo ngokwabo. Futhi kungumsebenzi oqhubekayo, kusakhula nsuku zonke."]}],"quips":{"1":"Igama elilodwa. Lilukhuni. Mhlawumbe lilukhuni kakhulu.","3":"Amagama amathathu. Seliqinisile kunamakhasi amaningi emikhiqizo.","8":"Amagama ayisishiyagalombili. Kusamfushane kuno-stand-up.","21":"Ubude bungamaphoyinti ezindaba, ngendlela. Yebo, kunjalo.","55":"Amagama angamashumi amahlanu nanhlanu. Amakhadi amabili aphelile ngenkathi ufunda lokho.","144":"Lena yinde. Alikho elingu-233. Ama-ejenti aye ukulala."}},"timeline":{"first-idea.name":"Umbono wokuqala","first-idea.line":"Ingxoxo yokuqala nya, ngaphambi kokuba kube khona ikhodi.","first-board.name":"Ibhodi lokuqala","first-board.line":"Ibhodi elilandelela ukwakhiwa kwalo: amakhadi, amakholomu, donsa uphonse, amaphrojekthi.","team-roles.name":"Iqembu nezindima","team-roles.line":"Amaphrofayela ama-ejenti, amathempulethi eqembu, izikhala nokuthi ngubani owenzani.","install.name":"Ukufaka nokukhishwa","install.line":"I-zip umngani angayifaka, ukuzibuyekeza, amashaneli nokubuyela emuva.","usage-saver.name":"Ukonga ukusetshenziswa","usage-saver.line":"Linganisa izindleko zokusebenza, gcina ikhodi incane, onge umkhawulo wakho.","friends.name":"Abangani nokwabelana","friends.line":"Imilayezo eyimfihlo, isidlulisi esixubekile, izimemo, izindima namaphrojekthi abelwanayo.","languages.name":"Izilimi","languages.line":"Yonke imibhalo yesikrini ifayelini lolimi, kuqala ngesiDashi nesiFlemish.","ai-tester.name":"Umhloli we-AI","ai-tester.line":"Umhloli uhlola ukudluliselwa ngakunye kuqala bese ekhombisa ayekubonile.","website.name":"Iwebhusayithi","website.line":"I-aigile.lol, i-teaser nalesi sikhathi.","streaming.name":"Ingxoxo nokusakaza","streaming.line":"I-Discord, i-Twitch, i-OBS, imodi yomsakazi, ama-GIF nama-emoji.","no-ai.name":"Uhlelo olungenayo i-AI","no-ai.line":"Ibhodi labantu abakhipha ikhodi ngaphandle kwe-AI, namabhodi omphakathi.","night-watch.name":"Ukuqapha ebusuku","night-watch.line":"Umqaphi ne-Scrum Master baqhubekisa amaqembu emsebenzini ngenkathi ulele.","p-more.name":"Konke okunye","p-more.line":"Imibono emincane ekhona isalindele ithuba layo.","p-android.name":"Ifoni ne-Android","p-android.line":"Finyelela ibhodi lakho ofonini, bese kuba uhlelo lwangempela lwe-Android.","p-release.name":"I-alpha nangale kwayo","p-release.line":"I-alpha evaliwe, isayithi eliphilayo, bese i-beta.","p-languages.name":"Izilimi eziningi","p-languages.line":"Izilimi ezingu-130, nemodi yokucwiliswa olimini yabafundi.","p-engines.name":"Izinjini ze-AI eziningi","p-engines.line":"Khetha i-Claude, i-Codex, i-Gemini, i-Copilot noma i-Cursor kusikhulumeli ngasinye.","p-pro.name":"Umkhuba wochwepheshe","p-pro.line":"Amalebula obungozi, amasango okuhlanganisa, amakhadi ezehlakalo nezivikelo.","p-self.name":"Ukukunakekela","p-self.line":"Imodi yokukhathala, izikhumbuzi zokuzinakekela ne-4:20.","p-servers.name":"Amaseva nobukhulu","p-servers.line":"Izilungiselelo zamaseva jikelele, izindima nokuhlela ukukhula.","p-livestream.name":"Okungeziwe kokusakaza","p-livestream.line":"Ingxoxo ye-Twitch, ama-emoji ngokwezifiso nombono womphakathi ophilayo."},"words":{"button":"📖 Amagama ochwepheshe","h":"📖 Amagama achaziwe","intro":"Ukuqeqeshwa mahhala ngolimi olulula: wonke igama ohlangana nalo kusukela embonweni wokuqala kuya enkonzweni abantu abayethembele kuyo, nge-Agile, ukwakha, ukuyigcina iphephile nokusebenza nge-AI endleleni.","search":"Sesha igama…","none":"Alikho igama elifana nalelo.","close":"Vala","count":{"one":"igama elingu-{count}","other":"amagama angu-{count}"},"groups":[{"id":"idea","name":"💡 Imibono nokuthola"},{"id":"plan","name":"🗺️ Ukuhlela umsebenzi"},{"id":"agile","name":"🔁 Izindlela zokusebenza ze-Agile"},{"id":"build","name":"🛠️ Ukwakha"},{"id":"test","name":"🧪 Ukuhlola nekhwalithi"},{"id":"change","name":"🔀 Ukushintsha ngokuphepha"},{"id":"run","name":"🛎️ Ukuqhuba isevisi"},{"id":"sec","name":"🔒 Ukuphepha nobumfihlo"},{"id":"ai","name":"🤖 Ukusebenza nge-AI"},{"id":"money","name":"💰 Imali namalayisense"}],"list":[{"id":"discovery","g":"idea","word":"Ukuthola (Discovery)","text":"Isigaba sokuqala sokuthola ukuthi iyiphi inkinga efanele ukuxazululwa nokuthi ixazululelwa bani, ngaphambi kokuba kwakhiwe lutho.","also":["isigaba sokuthola","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Isitatimende senkinga","text":"Imisho eyodwa noma emibili ethi ngubani onenkinga, iyini nokuthi kungani ibalulekile, ukuze wonke umuntu abheke endaweni eyodwa.","also":["izitatimende zezinkinga","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Umsebenzisi","text":"Umuntu osebenzisa lokho okwakhayo. Umsebenzi wenzelwa izidingo zakhe.","also":["abasebenzisi","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Obhekelele (Stakeholder)","text":"Noma ubani onendaba nokuthi umsebenzi uphumela kanjani noma othintwa yiwo, njengabantu abakhokhelayo, abawusebenzisayo noma abawusekelayo.","also":["ababhekelele","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"I-Persona","text":"Umuntu owakhiwe kodwa onokwenzeka, omele uhlobo olulodwa lomsebenzisi, ukuze iqembu likwazi ukubuza ukuthi “uSam angakuthola kulula yini lokhu?”","also":["ama-persona","persona","personas"]},{"id":"userresearch","g":"idea","word":"Ucwaningo lwabasebenzisi","text":"Ukukhuluma nabantu bangempela nokubabuka ukuze ufunde ukuthi badingani, kunokuthi uqagele.","also":["izingxoxo nabasebenzisi","user research","user interviews"]},{"id":"journey","g":"idea","word":"Uhambo lomsebenzisi","text":"Izinyathelo umuntu azithathayo ukuze enze okuthile, kusukela ekuzweni ngakho okokuqala kuze kube yilapho eqeda, naphandle komkhiqizo wakho. Ukukudweba kukhombisa lapho ebambeka khona.","also":["izinkambo zabasebenzisi","uhambo lweklayenti","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Indawo ebuhlungu (Pain point)","text":"Okuthile okucasula noma okubambezela abantu namuhla. Imikhiqizo emihle isusa izindawo ezibuhlungu.","also":["izindawo ezibuhlungu","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Okucatshangwayo (Assumption)","text":"Okuthile okukholelwayo kodwa ongakakuhloli. Ukubhala phansi okucatshangwayo kukhombisa ukuthi yini okufanele uhlole kuqala.","also":["okucatshangwayo","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Isiqagelo esizohlolwa (Hypothesis)","text":"Isiqagelo sakho esihle ohlela ukusihlola, kanye nalokho okulindele ukwenzeka, njengokuthi “abantu bazobhalisa uma inyanga yokuqala ingenamali”.","also":["iziqagelo ezizohlolwa","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Isivivinyo (Experiment)","text":"Isivivinyo esincane esihlelwe ukufunda ukuthi umbono uyasebenza yini, ngaphambi kokuthi uzibophezele kakhulu kuwo.","also":["izivivinyo","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Ubufakazi bomqondo (PoC)","text":"Umzamo osheshayo nongaqediwe wokubona ukuthi umbono ungasebenza yini nhlobo. Kuvame ukulahlwa uma usunempendulo.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Isifanekiso (Prototype)","text":"Imodeli yokuqala yomkhiqizo, imvamisa izithombe ezichofozekayo, ukuze uzame umbono kubantu ngaphambi kokuwakha kahle.","also":["izifanekiso","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Umdwebo olula wesikrini okhombisa lapho izinto zihlala khona, ngaphandle kwemibala noma okuqukethwe kwangempela.","also":["ama-wireframe","wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Isithombe esiphelele sokuthi isikrini sizobukeka kanjani, ngemibala nombhalo wangempela, kodwa akukho okusebenzayo okwamanje.","also":["ama-mockup","mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Izizathu zebhizinisi (Business case)","text":"Izizathu zokwenza iphrojekthi: ibiza malini, ilethani noma yonga malini, nobungozi bayo.","also":["izizathu zebhizinisi","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Ukufezeka (Feasibility)","text":"Ukuthi into ingakhiwa futhi ilondolozwe ngempela yini ngesikhathi, imali namakhono onawo.","also":["ukufezeka","feasibility"]},{"id":"outcome","g":"idea","word":"Umphumela","text":"Ushintsho olulindele kubantu, njengokuphuthelwa yimihlangano embalwa. Lubaluleke kakhulu kunokuthi wakhe kangakanani.","also":["imiphumela","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Okukhiqiziwe (Output)","text":"Okuthile okwenziwa yiqembu, njengesikrini esisha noma umbiko. Ukukwenza akusho ukuthi kusiza muntu.","also":["okukhiqiziwe","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Isilinganiso sempumelelo","text":"Inombolo ekutshela ukuthi umsebenzi wenze yini lokho obuwenzelwe, njengabantu abaningi abaqeda ama-oda abo.","also":["izilinganiso zempumelelo","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Isikhombi sokusebenza esikhulu (KPI)","text":"Inombolo ebalulekile oyibukayo ukuze ubone ukuthi izinto ziyahamba kahle yini, njengokubhalisa ngesonto.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Izinhloso nemiphumela eyinhloko (OKRs)","text":"Indlela yokubeka imigomo: inhloso ithi ufunani, futhi imiphumela embalwa eyinhloko yizinombolo ezikhombisa ukuthi ufikile.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Umkhiqizo","text":"Into eyakhiwayo futhi ilondolozelwa abasebenzisi bayo, njenge-app, iwebhusayithi noma ithuluzi.","also":["imikhiqizo","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Umbono womkhiqizo","text":"Isitatimende esifushane sokuthi umkhiqizo usiza bani nokuthi uya kuphi esikhathini eside.","also":["isitatimende sombono","vision statement"]},{"id":"po","g":"plan","word":"Umnikazi womkhiqizo (PO)","text":"Umuntu onquma ukuthi yini ezokhiwa nokuthi ngokulandelana okunjani, ukuze iqembu lihlale lisebenza kokubaluleke kakhulu. Ku-AI-gile ngowena lowo.","also":["abanikazi bomkhiqizo","PO","product owners"]},{"id":"pm","g":"plan","word":"Umphathi womkhiqizo (PM)","text":"Umuntu obheka isiqondiso somkhiqizo: yiziphi izinkinga oluxazululayo, kubani nokuthi kungani. I-PM ingasho nomphathi wephrojekthi, ngakho hlola ukuthi yikuphi.","also":["abaphathi bomkhiqizo","PM","product managers"]},{"id":"projmgr","g":"plan","word":"Umphathi wephrojekthi","text":"Umuntu ogcina iphrojekthi isesikhathini nasesabelomali, elandelela ukuthi ngubani owenzani nini.","also":["abaphathi bamaphrojekthi","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Imephu yomgwaqo (Roadmap)","text":"Uhlelo olubanzi lwalokho okuzayo ezinyangeni ezilandelayo, ngokulandelana. Lukhombisa isiqondiso, hhayi izinsuku eziqondile, futhi luyashintsha njengoba ufunda.","also":["roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Iphuzu elibalulekile (Milestone)","text":"Iphuzu eliphawulekayo ephrojekthini, njengokuthi “inguqulo yokuqala isiyaphila” noma “abasebenzisi abayi-100”.","also":["amaphuzu abalulekile","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Umkhiqizo omncane osebenzayo (MVP)","text":"Inguqulo encane kakhulu yomkhiqizo esewusizo ngempela kubantu, ukuze ufunde kubo kusenesikhathi.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Isidingo (Requirement)","text":"Okuthile umkhiqizo oqediwe okufanele ukwenze noma ube yikho.","also":["izidingo","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Ububanzi (Scope)","text":"Okufakiwe emsebenzini futhi, okubalulekile ngokulinganayo, okungafakiwe.","also":["ngaphakathi kobubanzi","ngaphandle kobubanzi","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Ukukhula komsebenzi (Scope creep)","text":"Uma kwengezwa okuningi nokuningi emsebenzini kancane kancane, kungekho muntu ovumelene ngesikhathi noma izindleko ezengeziwe, ngakho umsebenzi awupheli ngempela.","also":["feature creep","ukwengeza okuqhubekayo"]},{"id":"feature","g":"plan","word":"Isici (Feature)","text":"Into eyodwa umkhiqizo ongayenzela abantu, njengokuthi “setha kabusha iphasiwedi yakho”.","also":["izici","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"I-Epic","text":"Umsebenzi omkhulu kakhulu ongenziwa ngesikhathi esisodwa, ngakho uhlukaniswa ube amakhadi amancane.","also":["ama-epic","epic","epics"]},{"id":"story","g":"plan","word":"Indaba yomsebenzisi (User story)","text":"Umsebenzi omncane obhalwe ngohlangothi lomsebenzisi: “Njengomthengi, ngifuna ukugcina ubhasikidi wami, ukuze ngiqede kamuva.” Uqala ingxoxo ngokuthi yini okufanele yakhiwe.","also":["izindaba zabasebenzisi","user story","user stories"]},{"id":"ac","g":"plan","word":"Imibandela yokwamukelwa (AC)","text":"Ukuhlola okufanele ikhadi elilodwa lidlule ukuze lithathwe njengelaqediwe, okuvunyelwene ngakho ngaphambi kokuba umsebenzi uqale, njengokuthi “ubhasikidi usekhona ngemva kokuphuma ngingene futhi”.","also":["AC","acceptance criteria","imibandela yokwamukelwa"]},{"id":"task","g":"plan","word":"Umsebenzi omncane (Task)","text":"Umsebenzi oyedwa okufanele wenziwe, imvamisa isinyathelo esisodwa esincane sendaba enkulu.","also":["imisebenzi emincane","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"I-Ticket","text":"Elinye igama lekhadi: ucezu olulodwa lomsebenzi noma isicelo esisodwa, esilandelelwa kusukela ekuqaleni kuze kube sekugcineni.","also":["ama-ticket","ticket","tickets"]},{"id":"priority","g":"plan","word":"Okubekwa phambili (Priority)","text":"Ukuthi into ibaluleke noma iphuthuma kangakanani uma iqhathaniswa nakho konke okunye, ukuze umsebenzi obaluleke kakhulu wenziwe kuqala.","also":["priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Ukubeka phambili (Prioritisation)","text":"Ukubeka umsebenzi ngokulandelana kokubaluleka. Indlela evamile yi-MoSCoW: Kumele kube nakho, Kufanele kube nakho, Kungaba nakho, Ngeke kube nakho kulokhu.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Isilinganiselo (Estimate)","text":"Ukuqagela okuhle kakhulu ukuthi umsebenzi mkhulu kangakanani noma uzothatha isikhathi esingakanani. Kungukuqagela, hhayi isethembiso.","also":["izilinganiselo","ukulinganisela","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Amaphoyinti ezindaba (Story points)","text":"Indlela yokuqagela usayizi womsebenzi ngokuqhathanisa amakhadi (“cishe kukhulu kabili kunalelo”) kunokuba kube ngamahora. Akwenzelwe ukuqhathanisa amaqembu.","also":["iphoyinti lendaba","story points","story point"]},{"id":"tshirt","g":"plan","word":"Usayizi wehembe (T-shirt sizing)","text":"Ukuqagela usayizi womsebenzi ngo-S, M, L noma XL. Kuyashesha futhi kwanele ekuhleleni kwasekuqaleni.","also":["osayizi bamahembe","t-shirt sizes","T-shirt sizing"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Umdlalo wokulinganisa: wonke umuntu ubonisa ikhadi losayizi ngesikhathi esisodwa, bese labo abanenombolo ephezulu nephansi kakhulu bachaza ukuthi kungani.","also":["i-Scrum poker","Scrum poker"]},{"id":"dependency","g":"plan","word":"Ukuncika (Dependency)","text":"Uma ucezu olulodwa lomsebenzi lungakwazi ukuqala noma ukuphela kuze kube olunye seluqalile noma seluphelile.","also":["ukuncika","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Isivimbelo (Blocker)","text":"Noma yini evimbela umsebenzi ukuthi uqhubekele phambili ngalesi sikhathi, njengempendulo engekho noma ithuluzi eliphukile.","also":["izivimbelo","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Usuku lokugcina (Deadline)","text":"Usuku okufanele into iqedwe ngalo.","also":["izinsuku zokugcina","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Okuletshwayo (Deliverable)","text":"Okuthile okubambekayo okukhiqizwa umsebenzi bese kudluliselwa kwabanye, njengekhasi elisebenzayo noma umbiko.","also":["okuletshwayo","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Isibikezelo (Forecast)","text":"Ukubikezela okungenzeka kwenzeke, njengokuthi umsebenzi uzophela nini, ngokusekelwe kulokho osukwazi kuze kube manje.","also":["izibikezelo","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Isilinganiso (Metric)","text":"Noma yini oyilinganisayo futhi uyilandelele ngokuhamba kwesikhathi, njengenani lezivakashi zekhasi noma isikhathi esithathwa ukulungisa iphutha.","also":["izilinganiso","metric","metrics"]},{"id":"feedback","g":"plan","word":"Impendulo (Feedback)","text":"Lokho abantu bakutshela ngomsebenzi wakho, okuhle nokubi. Ukukuthola kusenesikhathi nangokuvamile kuyinhliziyo ye-Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Uhlu lokulinda lemibono nomsebenzi ongakahlelwa, okubaluleke kakhulu kuphezulu. Akukho okusetshenzwa kukho kuze kuhambe kuya ku-Okufanele kwenziwe."},{"id":"sprint","g":"agile","word":"Sprint","text":"Isikhathi esifushane, esimisiwe somsebenzi (imvamisa isonto elilodwa noma amabili, akukaze kudlule inyanga) onomgomo kanye nesethi evunyelwene yamakhadi okufanele aqedwe.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Ukubheka okusheshayo kwansuku zonke: ilungu ngalinye leqembu lenzeni, lenzani ngokulandelayo, nokuthi yini ebamisayo. Ku-Scrum kubizwa ngokuthi daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","scrum yansuku zonke"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Indlela yokusebenza lapho amakhadi ehamba phakathi kwezingqimba zebhodi (njengo-Okufanele kwenziwe, Kuyaqhubeka, Kuphelile) futhi iqembu likhawulela ukuthi kungakanani okuqhubekayo ngesikhathi esisodwa, ukuze umsebenzi uqhubeke ugeleza."},{"id":"wip","g":"agile","word":"Umkhawulo we-WIP","text":"I-WIP isifinyezo se-work in progress (umsebenzi oqhubekayo). Umkhawulo we-WIP yinani eliphezulu lamakhadi isingqimba okufanele sibambe ngesikhathi esisodwa, ukuze iqembu liqede izinto ngaphambi kokuqala ezengeziwe.","also":["WIP"]},{"id":"dod","g":"agile","word":"Incazelo yokuqeda","text":"Uhlu olufushane lwethimba lokuthi “kuqediwe” kusho ukuthini, njengokuthi kuhloliwe futhi kuchaziwe, ngaphambi kokuthi ikhadi linikezwe wena. Iwele layo, Incazelo yokulungela, isho ukuthi ikhadi licace ngokwanele nini ukuze liqalwe.","also":["Definition of Ready","DoD","DoR","Definition of Done"]},{"id":"retro","g":"agile","word":"Ukubuyekeza","text":"Ukubuka emuva njalo ngokuthi iqembu lisebenza kanjani, ukuvumelana ngento eyodwa noma ezimbili ezizokwenziwa kangcono ngokuzayo. Isifinyezo se-retrospective. Ku-AI-gile i-retro iphakamisa ushintsho ezindleleni zeqembu zokusebenza, bese wena uthi Hamba noma Hhayi okwamanje.","also":["i-retro","retro","retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"Ukuhlangana","text":"Bonke basize: abantu abaningi bayeka eminye imisebenzi ukuze balungise ndawonye into eyodwa ephuthumayo kuze kuxazululeke. Ku-AI-gile wonke amaqembu asiza kuphrojekthi eyodwa, kuyilapho amanye amaphrojekthi elinda.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Ku-Scrum, umuntu osiza iqembu lisebenze kahle: asuse okuliphazamisayo, agcine imihlangano iqhubeka futhi aqeqeshe imikhuba emihle, ngaphandle kokuyala muntu. Ku-AI-gile i-Lead Scrum Master ibona amakhadi abambekile, iqhuqhuzela amaqembu futhi ikukhumbuze ukuthi yini elindile, kuwo wonke amaphrojekthi.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Indlela yokusebenza ngezinyathelo ezincane: wakhe kancane, ubonise imiphumela yangempela kaningi, ufunde kulokho abantu abakushoyo bese ushintsha uhlelo ngenkathi uhamba, esikhundleni sokuhlela konke kusengaphambili.","also":["Agile development","agile ways of working","ukuthuthuka kwe-Agile"]},{"id":"manifesto","g":"agile","word":"Isimemezelo se-Agile (Agile Manifesto)","text":"Isitatimende esifushane esabhalwa ngo-2001 ngabenzi besofthiwe. Sibeka abantu, imiphumela esebenzayo, ukusebenza eduze namaklayenti nokuphendula ushintsho ngaphambi kwezinhlelo ezinzima nemibhalo eminingi.","also":["Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Indlela endala yokusebenza: hlela konke, bese wakha konke, bese uhlola konke, isigaba ngesigaba. Izinguquko sekwedlule isikhathi zinzima futhi ziyabiza.","also":["waterfall model","imodeli ye-waterfall"]},{"id":"iteration","g":"agile","word":"Umjikelezo (Iteration)","text":"Umjikelezo owodwa wokwakha okuthile, wokukuhlola nokukuthuthukisa. Umsebenzi we-Agile uyiketango lalokhu, futhi i-sprint luhlobo olulodwa lwawo.","also":["imijikelezo","iteration","iterations"]},{"id":"increment","g":"agile","word":"Ingxenye eyengeziwe (Increment)","text":"Ucezu olusha olusebenzayo olungezwe emkhiqizweni ku-sprint noma emjikelezweni womsebenzi, olufanelana nalokho obekukhona kakade.","also":["izingxenye ezengeziwe","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Indlela edumile ye-Agile yokusebenza: iqembu elincane lisebenza ngama-sprint amafushane lisondela emgomweni, linezindima ezisethiwe nemihlangano embalwa evamile yokuhlela, ukuhlola nokuthuthukisa."},{"id":"scrumteam","g":"agile","word":"Iqembu le-Scrum","text":"Iqembu elincane elenza umsebenzi ku-Scrum: umnikazi womkhiqizo, i-Scrum Master nabathuthukisi.","also":["amaqembu e-Scrum","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Imicimbi ye-Scrum","text":"Imihlangano evamile ku-Scrum: ukuhlela i-sprint, i-scrum yansuku zonke, ukubuyekeza i-sprint ne-retro. Abantu abaningi bayibiza ngokuthi ama-ceremony (imikhosi).","also":["Scrum events","ceremonies","Scrum ceremonies","imikhosi ye-Scrum"]},{"id":"sprintplan","g":"agile","word":"Ukuhlela i-sprint","text":"Umhlangano ekuqaleni kwe-sprint lapho iqembu livumelana ngokuthi kungani i-sprint ibalulekile, ukuthi yimaphi amakhadi elizowathatha nokuthi lizoqala kanjani.","also":["umhlangano wokuhlela","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Umgomo we-sprint","text":"Umusho owodwa othi i-sprint yenzelwani. Imisebenzi emincane ingashintsha endleleni, inqobo nje uma umgomo ufinyelelwa.","also":["imigomo ye-sprint","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"I-backlog ye-sprint","text":"Amakhadi akhethelwe i-sprint yamanje, nohlelo leqembu lokuwenza.","also":["ama-backlog e-sprint","sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"I-backlog yomkhiqizo","text":"Uhlu oluphelele nolulandelanisiwe lwakho konke okungakhiwa komkhiqizo, okubaluleke kakhulu phezulu. Luhlala lushintsha njengoba ufunda.","also":["ama-backlog omkhiqizo","product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Umgomo womkhiqizo","text":"Umphumela omkhulu umkhiqizo osebenzela wona, osiza iqembu likhethe okuzolandela.","also":["imigomo yomkhiqizo","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Ukucwenga i-backlog (Backlog refinement)","text":"Ukudlula ku-backlog njalo ukuze kuhlelwe, kuhlukaniswe, kulandelaniswe futhi kufakwe imininingwane emakhadini, ukuze alungele ukuthathwa. Kubizwa nangokuthi backlog grooming.","also":["backlog grooming","refinement","ukulungisa i-backlog"]},{"id":"sprintreview","g":"agile","word":"Ukubuyekeza i-sprint","text":"Umhlangano ekupheleni kwe-sprint lapho iqembu libonisa lokho eliqedile futhi lizwe ukuthi abantu bacabangani, ukuze kunqunywe ukuthi kulandela ini.","also":["izibuyekezo ze-sprint","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Idemo (Demo)","text":"Ukubonisa umsebenzi oqediwe usebenza, bukhoma, kubantu abawucele.","also":["amademo","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Ibhokisi lesikhathi (Timebox)","text":"Isikhathi esimisiwe sento. Uma siphela uyayeka, noma kungenzekanga konke.","also":["timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Isivinini (Velocity)","text":"Ukuthi umsebenzi omningi kangakanani iqembu elivame ukuwuqeda ku-sprint, osetshenziselwa ukuhlela ukuthi kuthathwe kangakanani ngokuzayo. Akuwona amaphuzu okukala ukuthi abantu basebenza kanzima kangakanani.","also":["isivinini seqembu","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Umthamo (Capacity)","text":"Ukuthi umsebenzi omningi kangakanani iqembu elingawuthatha esikhathini, ngemva kwezinsuku zokuphumula neminye imisebenzi.","noTip":1},{"id":"burndown","g":"agile","word":"Ishadi le-burndown","text":"Ishadi lomsebenzi osele ku-sprint, lehla usuku nosuku. Uma umugqa ungehli, kukhona okubambekile.","also":["burndown","burn-down chart","Burndown chart"]},{"id":"burnup","g":"agile","word":"Ishadi le-burnup","text":"Ishadi lomsebenzi oqediwe, likhuphuka ngokuhamba kwesikhathi, eduze kwesamba esihlelwe, ukuze ubone ukuthi uzofika nini.","also":["burnup","burn-up chart","Burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Ibhodi le-Kanban","text":"Ibhodi ngokwalo: isingqimba esisodwa ngesigaba ngasinye somsebenzi, namakhadi ahamba esuka kwesinye aye kwesinye.","also":["amabhodi e-Kanban","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Uhlelo lokudonsa (Pull system)","text":"Indlela yokusebenza lapho umsebenzi omusha uqala kuphela uma othile enendawo yokuwuthatha, esikhundleni sokuthi uphoqelelwe kothile osevele ematasa kakhulu.","also":["pull system","pull-based"]},{"id":"flow","g":"agile","word":"Ukugeleza (Flow)","text":"Ukuthi umsebenzi uhamba kahle kangakanani ebhodini. Ukugeleza okuhle kusho ukuthi amakhadi ayaqhubeka esikhundleni sokuqongelela.","also":["ukugeleza komsebenzi","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Isikhathi sokulethwa (Lead time)","text":"Isikhathi esithathwa kusukela uma othile ecela into kuze kube yilapho iqedwa.","also":["izikhathi zokulethwa","lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Isikhathi somjikelezo (Cycle time)","text":"Isikhathi ikhadi elisithatha kusukela uma umsebenzi uqala ngempela kulo kuze kube yilapho liqedwa.","also":["izikhathi zomjikelezo","cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Okuqedwayo (Throughput)","text":"Ukuthi mangaki amakhadi aqedwa ngesonto, noma kunoma yisiphi isikhathi esimisiwe.","also":["isilinganiso sokuqeda","throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Indawo ebambezelayo (Bottleneck)","text":"Isigaba esisodwa lapho umsebenzi uqongelela futhi ubambezele konke okungemuva, njengentamo emincane yebhodlela.","also":["izindawo ezibambezelayo","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"I-Swimlane","text":"Umugqa onqamula ibhodi ohlanganisa amakhadi ohlobo olulodwa, njengomsebenzi ophuthumayo noma amakhadi eqembu elilodwa.","also":["ama-swimlane","swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Indlela yokusebenza esusa ukumosha (noma yini engalisizi iklayenti) futhi igcine umsebenzi ugeleza."},{"id":"waste","g":"agile","word":"Ukumosha (Waste)","text":"Ku-Lean, noma yini ethatha umzamo kodwa engalisizi iklayenti, njengokulinda, ukwenza kabusha noma ukwakha izinto ezingasetshenziswa muntu.","noTip":1},{"id":"kaizen","g":"agile","word":"Ukuthuthuka okuqhubekayo","text":"Ukuba ngcono kancane ngaso sonke isikhathi ngezinguquko ezincane ezivamile, bese uhlola ukuthi zisizile yini. Ama-retro ayindlela eyodwa yokukwenza. Kubizwa nangokuthi kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Iqembu elizilungiselelayo","text":"Iqembu elizinqumela lona ukuthi lizokwenza kanjani umsebenzi, esikhundleni sokutshelwa isinyathelo ngesinyathelo.","also":["iqembu elizilawulayo","self-organising","self-organising team","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Iqembu lamakhono amaningi","text":"Iqembu elinawo wonke amakhono eliwadingayo ukuze liqede umsebenzi lona, njengokuklama, ukwakha nokuhlola.","also":["cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"I-Spike","text":"Ucwaningo olufushane, olunesikhathi esimisiwe, lokuphendula umbuzo ngaphambi kokuzibophezela emsebenzini wangempela.","also":["ama-spike","spike","spikes"]},{"id":"rework","g":"agile","word":"Ukwenza kabusha (Rework)","text":"Ukwenza umsebenzi futhi ngoba awuzange ulunge okokuqala.","also":["rework","reworked","ukuphinda umsebenzi"]},{"id":"safe","g":"agile","word":"I-Agile esikalini esikhulu (SAFe)","text":"Izindlela zokusebenzisa i-Agile emaqenjini amaningi enhlanganweni enkulu. I-SAFe (Scaled Agile Framework) isibonelo esisodwa esaziwa kakhulu.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Ifolda yephrojekthi yekhodi nomlando wayo ophelele wama-commit. Ingahlala kukhompyutha yakho, ku-GitHub, noma kokubili.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Umugqa ohlukile womsebenzi ekhodini, ukuze izinguquko zenziwe ngaphandle kokuthinta inguqulo eyinhloko.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Isithombe esigciniwe sekhodi, esinenothi elifushane lokushintshile. Ungabuyela kunye noma nini.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Ukuthumela izithombe zakho ezigciniwe (ama-commit) kusuka kukhompyutha yakho kuya ekhophini ebelwanayo ku-inthanethi, njenge-GitHub, ukuze zigcinwe ngokuphepha futhi abanye bazithole."},{"id":"merge","g":"build","word":"Merge","text":"Ukuhlanganisa izinguquko ezivela egatsheni elilodwa kolunye, imvamisa kubuyele enguqulweni eyinhloko."},{"id":"pr","g":"build","word":"Pull request","text":"Ukucela ukuthi izinguquko zegatsha zihlolwe futhi zihlanganiswe enguqulweni eyinhloko. Ezinye izindawo zikubiza ngokuthi merge request.","also":["PR","PRs","merge request","isicelo sokuhlanganisa"]},{"id":"refactor","g":"build","word":"Refactor","text":"Ukuhlela ikhodi ngaphandle kokushintsha okwenzayo: amafayela amancane, amagama acacile, ukuphindaphinda okuncane."},{"id":"bug","g":"build","word":"Bug","text":"Into engasebenzi ngendlela okufanele isebenze ngayo.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Ukubuyekezwa ngontanga","text":"Amehlo esibili: umuntu ongesiye owabhala uhlola umsebenzi ngaphambi kokuba ufike kuwe, ukuze kudlule amaphutha ambalwa. Ku-AI-gile enye i-AI ihlola ikhadi ngalinye.","also":["peer review","code review"]},{"id":"code","g":"build","word":"Ikhodi","text":"Iziqondiso ezibhaliwe ezitshela ikhompyutha ukuthi yenzeni. Ibizwa nangokuthi source code.","also":["ikhodi yomthombo","code","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Ulimi lokuhlela (Programming language)","text":"Ulimi lokubhala ikhodi, njenge-JavaScript, Python noma Java. Ezehlukene zifanele imisebenzi eyehlukene.","also":["izilimi zokuhlela","programming language","programming languages"]},{"id":"developer","g":"build","word":"Umthuthukisi (dev)","text":"Umuntu obhala futhi ashintshe ikhodi. Ubizwa nangokuthi umhleli wezinhlelo noma unjiniyela wesofthiwe.","also":["abathuthukisi","umhleli wezinhlelo","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Isofthiwe (Software)","text":"Izinhlelo ezisebenza kumakhompyutha nasezingcingweni, ngokungafani nemishini ngokwayo (i-hardware).","noTip":1},{"id":"app","g":"build","word":"I-App","text":"Isifinyezo se-application: uhlelo abantu abalusebenzisayo ukuze benze okuthile, ocingweni, kukhompyutha noma kusiphequluli sewebhu.","also":["ama-app","uhlelo lokusebenza","app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"I-web app","text":"I-app esebenza kusiphequluli sewebhu, ngakho akukho okudingeka kufakwe.","also":["ama-web app","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"I-Front end","text":"Ingxenye ye-app oyibonayo futhi oyiqhafazayo: izikrini, izinkinobho namagama, imvamisa kusiphequluli sakho.","also":["front-end","frontend","ingxenye ebonakalayo"]},{"id":"backend","g":"build","word":"I-Back end","text":"Ingxenye ye-app engemuva egcina idatha futhi yenza umsebenzi uma uqhafaza okuthile, njengokuhlola iphasiwedi yakho.","also":["back-end","backend","ingxenye engemuva"]},{"id":"fullstack","g":"build","word":"I-Full stack","text":"Ukusebenza kuyo yomibili i-front end ne-back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"Isixhumi sabasebenzisi (UI)","text":"Lokho umuntu akubonayo futhi akusebenzisayo esikrinini: ukwakheka, izinkinobho, amamenyu namagama.","also":["UI","user interface","i-interface"]},{"id":"ux","g":"build","word":"Isipiliyoni somsebenzisi (UX)","text":"Ukuthi kuzwakala kanjani ukusebenzisa okuthile: kulula, kuyacaca futhi kuyajabulisa, noma kuyadida futhi kuyahamba kancane.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Ukufinyeleleka (a11y)","text":"Ukwenza izinto zisetshenziswe yiwo wonke umuntu, kuhlanganise nabantu abangaboni kahle, abangakwazi ukusebenzisa imawusi noma abasebenzisa isifundi sesikrini.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Ukwakheka okuvumelanayo (Responsive design)","text":"Ukwenza amakhasi alingane futhi asebenze kahle kunoma yiluphi usayizi wesikrini, kusukela ocingweni kuya kumonitha enkulu.","also":["responsive design"]},{"id":"designsys","g":"build","word":"Uhlelo lokuklama (Design system)","text":"Isethi yemibala, amafonti, izinkinobho nemithetho eyabiwe, ukuze zonke izikrini zibukeke futhi zisebenze ngendlela efanayo.","also":["izinhlelo zokuklama","design system","design systems"]},{"id":"architecture","g":"build","word":"Isakhiwo sesistimu (Architecture)","text":"Isimo sonke sesistimu: yiziphi izingxenye eziyinhloko nokuthi zixhumana kanjani."},{"id":"database","g":"build","word":"Isizindalwazi (Database)","text":"Indawo ehlelekile yokugcina ulwazi, njenge-spreadsheet enamandla kakhulu i-app engayifunda futhi iyishintshe.","also":["database","databases","DB","isizindalwazi"]},{"id":"schema","g":"build","word":"Isakhiwo sesizindalwazi (Schema)","text":"Ukuhlelwa kwesizindalwazi: yimaphi amathebula olwazi esinawo nokuthi kungena ini kulelo nalelo.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Isifinyezo se-structured query language: ulimi olusetshenziselwa ukucela ulwazi kumasizindalwazi amaningi noma ukulushintsha.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Idatha (Data)","text":"Ulwazi olugcinwe yikhompyutha, njengamagama, ama-oda noma izilungiselelo.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Iseva (Server)","text":"Ikhompyutha ehlala ivuliwe futhi iphendula izicelo zamanye amakhompyutha, njengokuthumela ikhasi lewebhu uma ulivakashele.","also":["amaseva","server","servers"]},{"id":"client","g":"build","word":"Iklayenti (Client)","text":"Uhlangothi olucela okuthile, imvamisa isiphequluli noma i-app yakho, ekhuluma neseva. Ebhizinisini kusho nje umthengi.","also":["amaklayenti","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Isifinyezo se-application programming interface: imenyu esethiwe yezicelo okungenziwa uhlelo olulodwa kolunye, njengokucela isibikezelo sanamuhla enkonzweni yesimo sezulu.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"I-Endpoint","text":"Into eyodwa kumenyu ye-API: ikheli lewebhu uhlelo olungalibiza ukuze lithole noma lithumele okuthile.","also":["ama-endpoint","endpoint","endpoints"]},{"id":"integration","g":"build","word":"Ukuxhumanisa izinhlelo (Integration)","text":"Ukuxhumanisa izinhlelo ezimbili ukuze zisebenzisane, njengesitolo sakho sithumela ama-oda kusofthiwe yakho yama-akhawunti.","also":["ukuxhumanisa izinhlelo","integration","integrations"]},{"id":"webhook","g":"build","word":"I-Webhook","text":"Umlayezo uhlelo olulodwa oluthumela kolunye ngokwalo ngokushesha nje lapho kwenzeka okuthile, njengokuthi “inkokhelo isitholakele”.","also":["ama-webhook","webhook","webhooks"]},{"id":"library","g":"build","word":"Umtapo (Library)","text":"Ikhodi eselungile ebhalwe ngomunye umuntu ongayisebenzisa kabusha esikhundleni sokuzibhalela yona.","also":["imitapo","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Uhlaka (Framework)","text":"Isakhiwo esiselungile sokwakha i-app esinquma okuningi ngokuthi ikhodi ihlelwe kanjani, njengohlaka lwendlu obese uyalugcwalisa.","also":["izinhlaka","framework","frameworks"]},{"id":"sdk","g":"build","word":"Ikhithi yokuthuthukisa isofthiwe (SDK)","text":"Ibhokisi lamathuluzi, ikhodi nezibonelo zokwakha isofthiwe yeplatifomu eyodwa noma isevisi eyodwa.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Ukuncika kwesofthiwe (Software dependency)","text":"Umtapo noma ithuluzi ikhodi yakho elidingayo ukuze isebenze. Ukuzibuyekeza njalo kubalulekile ekuphepheni.","also":["software dependency","software dependencies"]},{"id":"package","g":"build","word":"Iphakheji (Package)","text":"Inqwaba yekhodi eselungile ongayifaka futhi uyisebenzise ephrojekthini.","also":["amaphakheji","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Umphathi wamaphakheji (Package manager)","text":"Ithuluzi elilanda futhi libuyekeze amaphakheji ikhodi yakho encike kuwo. I-npm ingenye evamile.","also":["abaphathi bamaphakheji","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Ithuluzi elisetshenziswa kakhulu lokugcina umlando wezinguquko zekhodi, njengama-commit namagatsha."},{"id":"github","g":"build","word":"GitHub","text":"Iwebhusayithi egcina ama-repo e-Git ku-inthanethi, ukuze amaqembu abelane ngekhodi, abuyekeze izinguquko futhi alandelele umsebenzi."},{"id":"vcs","g":"build","word":"Ukulawula izinguqulo (Version control)","text":"Ukugcina umlando ophelele wazo zonke izinguquko kumafayela, ukuze ubone ukuthi ngubani oshintshe ini futhi ubuyele emuva uma kudingeka. I-Git iyakwenza lokhu.","also":["source control","version control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Ukwenza ikhophi yakho ephelele ye-repo, nomlando wayo, kukhompyutha yakho.","also":["clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Ukulanda ama-commit akamuva avela ekhophi ebelwanayo (njenge-GitHub) kukhompyutha yakho. Okuphambene ne-push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Igatsha elikhulu (Main branch)","text":"Inguqulo esemthethweni yekhodi wonke umuntu asebenza kuyo, ebizwa kaningi ngokuthi main noma master.","also":["igatsha eliyinhloko","main branch","master branch"]},{"id":"conflict","g":"build","word":"Ukungezwani kokuhlanganisa (Merge conflict)","text":"Uma izinguquko ezimbili zithinta imigqa efanayo ngezindlela ezihlukile, ngakho ikhompyutha ayikwazi ukuzihlanganisa futhi umuntu kumele akhethe.","also":["merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Ukubuka okukhombisa ngqo ukuthi yini eshintshile phakathi kwezinguqulo ezimbili: imigqa engeziwe nemigqa esusiwe.","also":["ama-diff","diff","diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Ikhophi yakho ye-repo yomunye umuntu, ongayishintsha ngaphandle kokuthinta eyakhe.","also":["ama-fork","fork","forks","forked"]},{"id":"script","g":"build","word":"Iskripthi (Script)","text":"Uhlelo olufushane olwenza umsebenzi owodwa ngokwalo, njengokuhlela amafayela noma ukuqala i-app.","also":["iskripthi","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Ukuguqula ikhodi ibe yinto eselungele ukusebenza, noma umphumela ongokwawo osulungele ukusebenza.","also":["build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Ukuhumusha ikhodi ebhalwe abantu ibe yifomu ikhompyutha engayisebenzisa ngqo.","also":["ukuhumusha ikhodi","compile","compiler"]},{"id":"cli","g":"build","word":"Umugqa womyalo (CLI)","text":"Iwindi lombhalo lapho uthayipha iziqondiso zekhompyutha esikhundleni sokuqhafaza. Libizwa nangokuthi i-terminal.","also":["command line","command-line","CLI","terminal","i-terminal"]},{"id":"config","g":"build","word":"Ukucushwa (config)","text":"Izilungiselelo ezilawula indlela isofthiwe esebenza ngayo, ezigcinwe ngokwehlukile kukhodi ukuze kube lula ukuzishintsha.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"I-environment variable","text":"Isilungiselelo esinikezwa uhlelo uma luqala, esivame ukusetshenziselwa amakheli noma amaphasiwedi ukuze angabhalwa ekhodini.","also":["environment variable","environment variables","env var","ama-environment variable"]},{"id":"debugging","g":"build","word":"Ukususa amaphutha (Debugging)","text":"Ukuzingela ukuthi kungani into ingasebenzi, bese uyilungisa.","also":["debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Ukuhlela ngababili (Pair programming)","text":"Abantu ababili (noma umuntu ne-AI) basebenza ndawonye ekhodini efanayo, omunye uthayipha omunye uhlola.","also":["pairing","pair programming"]},{"id":"docs","g":"build","word":"Imibhalo echazayo (Documentation, docs)","text":"Izincazelo ezibhaliwe zokuthi into isebenza kanjani noma ukuthi isetshenziswa kanjani.","also":["documentation","docs","imibhalo yokusiza"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Ifayela lokuqala okufanele ulifunde ku-repo: ukuthi iphrojekthi iyini nokuthi uyiqalisa kanjani.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Uhlelo lwakudala (Legacy system)","text":"Uhlelo oludala olusasetshenziswa olunzima ukuluguqula, imvamisa ngoba bambalwa abantu abasaluqondayo.","also":["legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Isikweletu sobuchwepheshe (Technical debt)","text":"Izindlela ezimfushane ezonga isikhathi manje kodwa zenze izinguquko zakamuva zihambe kancane, njengesikweletu esikhula nenzalo. I-refactor iyasinciphisa.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Ukuhlola ukuthi into isebenza ngendlela okufanele yini. Ezinye izivivinyo ikhompyutha iziqhuba yodwa njalo uma ikhodi ishintsha; ezinye wukuzama kwakho ikhadi eliqediwe ngaphambi kokuba ulamukele.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Isifinyezo se-quality assurance: konke okwenziwa ukuqinisekisa ukuthi umsebenzi ulungile ngaphambi kokuba uphile. Ku-AI-gile lokho kusho ukuhlolwa okuzenzakalelayo: uma i-QA ibomvu, okuthile kwehlulekile, futhi ayikwazi ukuphila kuze kulungiswe.","also":["ukuhlolwa kwekhwalithi","quality assurance","quality checks"]},{"id":"testpile","g":"test","word":"Isitaki sokuhlola","text":"Amakhadi aqediwe alinde ukuthi uwazame, elinye emva kwelinye. Yamukela elilodwa noma ulibuyisele nenothi, bese kuvela elilandelayo.","also":["test pile","test piles"]},{"id":"autotest","g":"test","word":"Ukuhlola okuzenzakalelayo (Automated test)","text":"Ukuhlola ikhompyutha ekwenza ngokwayo njalo uma ikhodi ishintsha, ukubamba amaphutha kusenesikhathi.","also":["automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Ukuhlola ngesandla (Manual test)","text":"Umuntu ozama umsebenzi ngesandla ukuze abone ukuthi uyenza ngendlela efanele yini.","also":["manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Ukuhlola iyunithi (Unit test)","text":"Ukuhlola okuzenzakalelayo okuncane kocezu olulodwa oluncane lwekhodi lodwa.","also":["unit test","unit tests"]},{"id":"integtest","g":"test","word":"Ukuhlola ukuhlanganisa (Integration test)","text":"Ukuhlola ukuthi izingxenye eziningana zisebenza kahle ndawonye, hhayi eyodwa ngesikhathi.","also":["integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Ukuhlola kusukela ekuqaleni kuya ekugcineni (E2E)","text":"Ukuhlola okwenza njengomsebenzisi wangempela kusukela ekuqaleni kuze kube sekugcineni, njengokubhalisa, ukuthenga nokukhokha.","also":["E2E","end-to-end tests","End-to-end test"]},{"id":"uat","g":"test","word":"Ukuhlolwa kokwamukelwa abasebenzisi (UAT)","text":"Abantu abacele umsebenzi bawuzama bona ngokwabo bese bethi uyakwenza yini abakudingayo. Isitaki sokuhlola se-AI-gile siyinguqulo yalokhu.","also":["UAT","acceptance testing","User acceptance testing"]},{"id":"regression","g":"test","word":"I-Regression","text":"Okuthile okwakusebenza kodwa kwaphuka ngemva kokushintsha. Ukuhlola kwe-regression kuhlola ukuthi izinto zakudala zisasebenza yini.","also":["regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Ukuhlola okusheshayo (Smoke test)","text":"Ukuhlola okusheshayo kakhulu ukuthi izinto eziyinhloko zisebenza nhlobo yini, isibonelo ngokushesha ngemva kokuba inguquko iphile. Uma kwehluleka, yima bese ubheka.","also":["smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Ukuhlola ngokuhlolisisa (Exploratory testing)","text":"Ukuzama umkhiqizo ngokukhululeka futhi uwuhlolisise ngezindlela ezihlukene, ukuze uthole izinkinga ukuhlola okuhleliwe obekungeke kuzibone.","also":["exploratory test","exploratory tests","exploratory testing"]},{"id":"testcase","g":"test","word":"Isimo sokuhlola (Test case)","text":"Isimo esisodwa esibhaliwe sokuzama: izinyathelo, nalokho okufanele kwenzeke.","also":["test case","test cases"]},{"id":"coverage","g":"test","word":"Ukumbozwa kokuhlola (Test coverage)","text":"Ukuthi ingakanani ikhodi ehlolwa ukuhlola okuzenzakalelayo. Ngokuvamile okwengeziwe kuphephile kakhulu, kodwa ukumbozwa okuphezulu kuphela akufakazeli ukuthi isebenza kahle.","also":["code coverage","test coverage"]},{"id":"testdata","g":"test","word":"Idatha yokuhlola (Test data)","text":"Ulwazi lwesibonelo olwenziwe ukuze lusetshenziswe ngenkathi kuhlolwa, ukuze imininingwane yangasese yomuntu wangempela ingadalulwa.","also":["test fixtures","test data"]},{"id":"edgecase","g":"test","word":"Isimo somkhawulo (Edge case)","text":"Isimo esingajwayelekile emikhawulweni, njengefomu elingenalutho noma igama elinophawu lwe-apostrophe ('), lapho izinto zivame ukuphuka khona.","also":["edge case","edge cases","izimo zomkhawulo"]},{"id":"happypath","g":"test","word":"Indlela ejabulisayo (Happy path)","text":"Indlela evamile lapho yonke into iya kahle. Ukuhlola okuhle kuzama nezindlela ezingajabulisi."},{"id":"perftest","g":"test","word":"Ukuhlola ukusebenza (Performance testing)","text":"Ukuhlola ukuthi into isheshe kangakanani nokuthi ikwazi kanjani ukumelana nengcindezi.","also":["performance test","performance tests","performance testing"]},{"id":"loadtest","g":"test","word":"Ukuhlola umthwalo (Load testing)","text":"Ukuhlola ukuthi isistimu imelana kanjani uma abantu abaningi beyisebenzisa ngesikhathi esisodwa.","also":["load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Ukuhlola ukuphepha (Security testing)","text":"Ukubheka ubuthakathaka obungavumela umuntu ukuthi asebenzise kabi isistimu noma abone lokho okungafanele akubone.","also":["security test","security tests","security testing"]},{"id":"accesstest","g":"test","word":"Ukuhlola ukufinyeleleka (Accessibility testing)","text":"Ukuhlola ukuthi abantu abanamakhono ahlukene bangawusebenzisa yini umkhiqizo, kuhlanganise nesifundi sesikrini noma ikhibhodi kuphela.","also":["accessibility test","accessibility testing"]},{"id":"linting","g":"test","word":"Linting","text":"Ukuhlola okuzenzakalelayo okubona amaphutha angase abe khona nesitayela esingahlelekile ekhodini, njengesihloli sokupela sezinhlelo.","also":["linter","lint","linting"]},{"id":"static","g":"test","word":"Ukuhlaziywa okungashukumi (Static analysis)","text":"Ukuhlola ikhodi ukuthola izinkinga ngokuyifunda ngokuzenzakalelayo, ngaphandle kokuyiqhuba.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Ukuhlola okungathembekile (Flaky test)","text":"Ukuhlola kwesinye isikhathi okuphumelelayo nesinye isikhathi okwehlulekayo ngaphandle kwesizathu esicacile, ngakho akunakwethenjwa ngokuphelele.","also":["flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Ukuphinda iphutha (Reproduce, repro)","text":"Ukwenza iphutha lenzeke futhi ngamabomu ngokulandela izinyathelo ezifanayo, ukuze lifundwe futhi lilungiswe. Ukubhala phansi lezo zinyathelo yingxenye ewusizo kakhulu embikweni wephutha.","also":["repro","reproduce","steps to reproduce","izinyathelo zokuphinda"]},{"id":"severity","g":"test","word":"Ubukhulu benkinga (Severity)","text":"Ukuthi umthelela wenkinga ubi kangakanani, kusukela ekucasukeni okuncane kuya ekumeni kwayo yonke into.","also":["severity level","izinga lobukhulu benkinga"]},{"id":"deploy","g":"change","word":"Deploy","text":"Ukukopisha inguqulo entsha yesofthiwe emakhompyutheni ayisebenzisayo, njengekhophi yokuhlola noma isevisi ephilayo."},{"id":"release","g":"change","word":"Ukukhishwa","text":"Iqoqo elinegama lomsebenzi oqediwe eliphila ndawonye, linamanothi amafushane ngokushintshile. 🚀 Ukukhishwa kubhala lawo manothi kusuka emakhadini aqediwe.","also":["i-release","release","releases"]},{"id":"rollback","g":"change","word":"Ukubuyela emuva","text":"Ukubuyela enguqulweni yokugcina ebisebenza uma entsha idala inkinga. Ku-AI-gile, Roll back ihlanganisa izinyathelo zokuhoxisa ezibhalwe kushintsho ngalunye zibe uhlu olulodwa lokuhlola.","also":["i-rollback","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"Okuphilayo","text":"Inguqulo yangempela abantu abayisebenzisayo, hhayi ikhophi yokuzama izinto. Ukufaka okuthile lapho kubizwa ngokukuphilisa. Abathuthukisi bakubiza nangokuthi i-production.","also":["ukuphila","bukhoma","live","production"],"noTip":1},{"id":"change","g":"change","word":"Ushintsho","text":"Ushintsho oluhleliwe entweni abantu abathembele kuyo, olubhalwa kuqala: yini, kungani, ubungozi, nini, nokuthi lungahlehliswa kanjani. Qala ngokuthi 🔀 Phakamisa ushintsho.","also":["isicelo soshintsho","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Ubungozi","text":"Okuthile okungahamba kabi, okulinganiswa ngokuthi kungenzeka kangakanani nokuthi kungaba kubi kangakanani. ⚠️ Ubungozi kukugcina ohlwini olulodwa, amaphuzu aphezulu kuqala, ngakunye kunosuku lokuphinde ukubheke.","also":["izingozi","irejista yobungozi","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"Iwindi loshintsho","text":"Izikhathi lapho izinguquko zingaphila khona, njengobusuku bangoLwesibili obuthule. Ngaphandle kwewindi ikhadi loshintsho alikwazi ukuqedwa, ngaphandle uma kuyisimo esiphuthumayo.","also":["amawindi ezinguquko","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Ukuhlola kokugcina ngaphambi nje kokuba ushintsho luphile: umuntu ngamunye okumele avume uthi Go noma No go. Luqhubeka kuphela uma wonke umuntu ethi Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Ukuvunywa","text":"Ukulinda u-yebo ngaphambi kokuthi umsebenzi uqale. Ikhadi eliphakanyiswe ngumngane, noma ushintsho, kulinda ku-✅ Ukuvunywa uze ukuvume noma ukwenqabe.","also":["ukuvuma","approval","approvals"]},{"id":"quiettime","g":"change","word":"Isikhathi sokuthula","text":"Isikhathi, njengesikhathi sokusakaza bukhoma, idemo noma ubusuku, lapho kungaphili lutho. Amaqembu aqhubeka nokusebenza nokuhlola, kodwa ukuphila kulinda kuze kuphele. Kwenye indawo kubizwa ngokuthi change freeze.","also":["izikhathi zokuthula","quiet time","quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Indlela yokusebenza lapho abantu abakha isofthiwe nalabo abayiphethe basebenza njengeqembu elilodwa, ngokuzenzakalelayo okuningi, ukuze izinguquko ziphile kaningi futhi ngokuphepha."},{"id":"cicd","g":"change","word":"CI/CD (ukuhlanganisa nokulethwa okuqhubekayo)","text":"Izinguquko zawo wonke umuntu ziyahlanganiswa enguqulweni eyinhloko kaningi futhi ziyahlolwa ngokuzenzakalelayo njalo (ukuhlanganisa okuqhubekayo), ukuze isofthiwe ihlale ilungele ukuphila ngokucindezela inkinobho (ukulethwa okuqhubekayo).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Ukukhipha okuqhubekayo (Continuous deployment)","text":"Isinyathelo esisodwa ngaphezu kokulethwa okuqhubekayo: yonke inguquko edlula ekuhlolweni iphila yodwa, akukho nkinobho okumele icindezelwe.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Ipayipi (Pipeline)","text":"Uchungechunge oluzenzakalelayo lwezinyathelo inguquko eludlulayo endleleni eya ekuphileni, njengokwakha, ukuhlola, bese kukhishwa.","also":["amapayipi","pipeline","pipelines"]},{"id":"environment","g":"change","word":"I-Environment","text":"Ikhophi eyodwa ehlukile yesistimu enenhloso eyodwa, njengenye yokwakha kuyo, enye yokuhlola kuyo neyaphilayo.","also":["ama-environment","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"I-environment yokuthuthukisa (Development environment)","text":"Ikhophi umthuthukisi asebenza kuyo, imvamisa kukhompyutha yakhe, lapho ukophula izinto kungalimazi muntu.","also":["dev environment","development environment"]},{"id":"testenv","g":"change","word":"I-environment yokuhlola (Test environment)","text":"Ikhophi ehlukile yesistimu esetshenziselwa ukuhlola kuphela, ukuze isevisi yangempela ingathintwa.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"I-Staging","text":"Ikhophi yokugcina esethwe njengeyaphilayo, yokuhlola kokugcina ngaphambi kokuba inguquko iphile.","also":["staging","staging environment"]},{"id":"artifact","g":"change","word":"Umphumela we-build (Build artifact)","text":"Ifayela noma iqoqo i-build elikhiqizayo, elilungele ukugcinwa, ukuhlolwa noma ukuphila.","also":["build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Ukulungisa okuphuthumayo (Hotfix)","text":"Ukulungisa okuphuthumayo okukhishwa ngokushesha, ngaphandle kohlelo olujwayelekile, ngoba okuthile okubalulekile kuphukile.","also":["hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Ipatch (Patch)","text":"Isibuyekezo esincane esilungisa iphutha noma sivala imbobo yokuphepha. Ukufaka ama-patch okuphepha ngokushesha kubalulekile.","also":["patch","patches","security patch","security patches","ipatch"]},{"id":"version","g":"change","word":"Inombolo yenguqulo (Version number)","text":"Ilebuli efana ne-2.4.1 ekutshela ukuthi unayiphi inguqulo. Imvamisa inombolo yokuqala ishintsha ezinguqukweni ezinkulu neyokugcina ekulungisweni okuncane.","also":["version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Amanothi enguqulo (Release notes)","text":"Uhlu olufushane nolulula lwalokho okushintshile enguqulweni, olwabantu abayisebenzisayo, kuhlanganise nokulungisiwe nemikhawulo eyaziwayo. Kubizwa nangokuthi changelog.","also":["changelog","change log","release notes"]},{"id":"flag","g":"change","word":"Ifulegi lesici (Feature flag)","text":"Iswishi yokuvula nokuvala yesici, ukuze umsebenzi omusha uphile ufihlekile bese uvulwa (noma uvalwe futhi) ngaphandle kwenguqulo entsha.","also":["feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Ukulungisa inguqulo embi ngokukhipha ngokushesha inguqulo entsha elungisiwe esikhundleni sokubuyela kweyakudala.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Ukukhishwa kwe-canary (Canary release)","text":"Ukuphilisa inguquko kuqala eqenjini elincane, bese kubo bonke kuphela uma ibukeka kahle. Igama lithathwe ezinyoni ze-canary abasebenzi basezimayini ababehamba nazo ngaphansi komhlaba njengesixwayiso sokuqala.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Ukukhipha kwe-blue-green (Blue-green deployment)","text":"Ukugcina amakhophi amabili esistimu ephilayo bese ushintshela abantu kweyodwa entsha ngesikhathi esisodwa, ukuze ukwazi ukubuyela ngqo uma kungahambi kahle.","also":["blue-green","blue green deployment","Blue-green deployment"]},{"id":"zerodown","g":"change","word":"Ukukhipha ngaphandle kokumisa (Zero-downtime deployment)","text":"Ukuphilisa inguqulo entsha ngaphandle kokuba isevisi ime nanini kubasebenzisi bayo.","also":["zero downtime","zero-downtime","Zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Ukusiza izinguquko (Change enablement)","text":"Ukusiza izinguquko ziphumelele: ukukala ubungozi, ukuthola imvume efanele nokukhetha isikhathi esihle. Kubizwa nangokuthi change management.","also":["change management","change enablement","ukuphatha izinguquko"]},{"id":"cab","g":"change","word":"Ibhodi eluleka ngezinguquko (CAB)","text":"Iqembu elibheka izinguquko ezibalulekile bese livuma ukuthi zingaqhubeka yini nokuthi nini.","also":["CAB","Change advisory board"]},{"id":"stdchange","g":"change","word":"Ushintsho olusezingeni (Standard change)","text":"Ushintsho olunobungozi obuphansi olwenziwa ngendlela efanayo ehloliwe njalo, ngakho luvunywa kusengaphambili.","also":["standard change","standard changes"]},{"id":"normchange","g":"change","word":"Ushintsho olujwayelekile (Normal change)","text":"Ushintsho oludinga ukuhlolwa nokuvunywa ngaphambi kokuba luqhubeke.","also":["normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Ushintsho oluphuthumayo (Emergency change)","text":"Ushintsho okufanele lwenzeke ngokushesha ukulungisa noma ukuvimba inkinga enkulu, ngemvume esheshayo ehambisana nalo.","also":["emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Ukuzenzakalela (Automation)","text":"Ukwenza ikhompyutha yenze umsebenzi ophindaphindwayo ngokwayo, ukuze isheshe futhi yenziwe ngendlela efanayo njalo.","also":["automated","automation"],"noTip":1},{"id":"infra","g":"change","word":"Ingqalasizinda (Infrastructure)","text":"Imishini, amanethiwekhi nezinsiza isofthiwe esebenza kuzo.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Ingqalasizinda njengekhodi (IaC)","text":"Ukuchaza amaseva akho nezilungiselelo kumafayela agcinwe nekhodi, ukuze akwazi ukwakhiwa kabusha ngendlela efanayo njalo.","also":["IaC","Infrastructure as code"]},{"id":"cloud","g":"change","word":"Ifu (Cloud)","text":"Ukuqasha amakhompyutha, isitoreji nezinsiza kumhlinzeki omkhulu nge-inthanethi, esikhundleni sokuba umnikazi wemishini ngokwakho.","also":["ifu","the cloud","cloud computing","cloud"]},{"id":"provider","g":"change","word":"Umhlinzeki wefu (Cloud provider)","text":"Inkampani eqashisa ngamakhompyutha nge-inthanethi, njenge-Amazon Web Services (AWS), Microsoft Azure noma Google Cloud.","also":["abahlinzeki befu","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Ukusingathwa (Hosting)","text":"Lapho i-app yakho noma iwebhusayithi yakho ihlala futhi isebenza khona ukuze abantu bayifinyelele, imvamisa iqashwa enkampanini.","also":["ukusingathwa","hosting","i-hosting"]},{"id":"domain","g":"change","word":"Igama lesizinda (Domain name)","text":"Ikheli lewebhu abantu abalithayipha, njenge-example.com. Uliqasha ngonyaka, ngakho kufanele livuselelwe.","also":["amagama ezizinda","domain name","domain names","domain","isizinda"]},{"id":"dns","g":"change","word":"DNS","text":"Isifinyezo se-domain name system: incwadi yamakheli ye-inthanethi, eguqula igama elinjenge-example.com libe ikheli lekhompyutha efanele.","also":["domain name system"]},{"id":"container","g":"change","word":"I-Container","text":"Iphakheji elivaliwe elibamba i-app nakho konke eyikudingayo, ukuze isebenze ngendlela efanayo kunoma iyiphi ikhompyutha. I-Docker ithuluzi eliyaziwa kakhulu.","also":["ama-container","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Umshini we-virtual (VM)","text":"Ikhompyutha yokuzenzisa esebenza ngaphakathi kweyangempela, ukuze umshini omkhulu owodwa usebenze njengemishini eminingi.","also":["VM","VMs","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Ngaphandle kweseva (Serverless)","text":"Ukusebenzisa ikhodi ngaphandle kokunakekela noma yimaphi amaseva ngokwakho: umhlinzeki uyiqhuba uma kudingeka futhi ukhokha kuphela lokho osebenzisile."},{"id":"lb","g":"change","word":"Isilinganisi somthwalo (Load balancer)","text":"Okuthile okusabalalisa izivakashi phakathi kwamaseva amaningana, ukuze kungabikho neyodwa ethwaliswa kakhulu.","also":["izilinganisi zomthwalo","load balancer","load balancers"]},{"id":"cache","g":"change","word":"I-Cache","text":"Indawo yokugcina eseduze yemiphumela yakamuva, ukuze into efanayo ingadingi ukulandwa noma ukwenziwa futhi. Ukuyisula kungalungisa amakhasi abukeka endala.","also":["ama-cache","cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Inethiwekhi yokulethwa kokuqukethwe (CDN)","text":"Iqoqo lamaseva emhlabeni wonke eligcina amakhophi amakhasi nezithombe zakho eduze nezivakashi zakho, ukuze zilayishe ngokushesha.","also":["CDN","Content delivery network"]},{"id":"migration","g":"change","word":"Ukuthuthela (Migration)","text":"Ukuthuthela idatha noma izinhlelo kusuka ekusetheni okudala kuya kokusha, noma ukushintsha ngokucophelela ukuthi isizindalwazi sihlelwe kanjani.","also":["ukuthuthela","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Isevisi","text":"Okuthile okwakhile abantu abathembele kukho, njengewebhusayithi noma i-app, okunakekelwayo ukuze kuqhubeke kusebenza. Khetha ukuthi “Le phrojekthi iyisevisi” bese usho ukuthi inikezani, ubani oyisebenzisayo nokuthi ubani olindile.","also":["amasevisi","service","services"]},{"id":"uptimepct","g":"run","word":"I-Uptime","text":"Ukuthi ingakanani isikhathi isevisi isebenza ngaso, imvamisa njengephesenti. I-99.9% isavumela cishe imizuzu engama-43 ingasebenzi ngenyanga.","also":["uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Ukuhlola i-uptime","text":"Ukuhlola okuzenzakalelayo, njalo ngemizuzu embalwa, ukuthi isevisi yakho isaphendula yini. Uma kwehluleka izikhathi eziningana kulandelana, i-AI-gile ivula ikhadi lesigameko ngokwayo.","also":["uptime checks","ukuhlola i-uptime"]},{"id":"statuspage","g":"run","word":"Ikhasi lesimo","text":"Ikhasi lomphakathi elikhombisa ukuthi isevisi iyasebenza yini (eluhlaza, ewolintshi noma ebomvu) kanye nesibuyekezo sakamuva, ukuze abantu abayisebenzisayo bazibonele esikhundleni sokubuza.","also":["amakhasi esimo","status page","status pages"]},{"id":"desk","g":"run","word":"Idesiki lesevisi","text":"Lapho imibuzo nemibiko evela kubantu abasebenzisa isevisi yakho ingena khona. I-AI-gile ihlela ngamunye ube yisicelo, isigameko noma umcabango, futhi ikutshele uma kubukeka kufana nokuthile osekubikiwe.","also":["amadesiki esevisi","idesiki losizo","idesiki","service desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Isicelo sesevisi","text":"Umuntu ocela okuthile okujwayelekile, njenge-akhawunti entsha noma usizo oluncane, kunokuba abike ukuthi kukhona okuphukile. Silinda ithuba laso; isigameko siza kuqala.","also":["izicelo zesevisi","isicelo","service request","service requests"]},{"id":"incident","g":"run","word":"Isigameko","text":"Okuthile okuphukile noma okungasebenzi kahle kubantu abakusebenzisayo manje, njengewebhusayithi engasebenzi noma ehamba kancane kakhulu. Ikhadi lesigameko elinophawu lwe-🔥 liweqa ulayini: ukuyenza isebenze futhi kuza kuqala.","also":["izigameko","incident","incidents"]},{"id":"major","g":"run","word":"Isigameko esikhulu","text":"Isigameko esikhulu: abantu abaningi bathintekile, noma imali noma idatha isengozini. Inkinobho eyodwa ibeka wonke amathimba kuso (ukuhlangana), ivuse noma ubani olindile bese icela isibuyekezo sesimo njalo ngemizuzu engu-30.","also":["izigameko ezinkulu","major incident","major incidents"]},{"id":"oncall","g":"run","word":"Ukulinda","text":"Ukuba ngulowo ophendulayo uma kukhona okuphukayo, ngisho nasebusuku. Isevisi ngayinye inelungu lethimba elilindile elivuswa kuqala ezigamekweni zayo.","also":["olindile","on call","on-call"]},{"id":"replyby","g":"run","word":"Isikhathi sokuphendula","text":"Ukuthi ikhadi lingalinda isikhathi esingakanani impendulo yokuqala, isibonelo ihora elilodwa esigamekweni. Ngemva kwalokho lithola iwashi elibomvu, ukuze kungabikho okukhohlwakala buthule. Kubizwa nangokuthi i-response target.","also":["reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"Ukuhlaziywa kwesigameko","text":"Ukubheka emuva okufushane ngemva kwesigameko: kwenzekeni, yini esizile nokuthi yini okufanele ishintshwe, ngaphandle kokusola muntu. Isigameko asikwazi ukuvalwa ngaphandle kwakho. Kubizwa nangokuthi i-post-mortem.","also":["post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Inkinga","text":"Imbangela efihlekile ngemuva kwesigameko esisodwa noma ngaphezulu. Ikhadi lenkinga 🧩 liqoqa izigameko eziqhubeka zibuya, ukuze imbangela itholakale ilungiswe unomphela.","also":["izinkinga","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Imbangela eyinhloko","text":"Isizathu sangempela sokuthi kungani okuthile kuphukile, hhayi nje lokho okubone kungahambi kahle. Lungisa imbangela eyinhloko bese isigameko siyeka ukubuya.","also":["izimbangela eziyinhloko","root cause","root causes"]},{"id":"workaround","g":"run","word":"Indlela yesikhashana","text":"Indlela yokugcina izinto zisebenza kuze kube yilapho ukulungisa kwangempela sekulungile, njengokuqala kabusha okuthile uma kubambeka. Ibhalwa ekhadini lenkinga ukuze kungabikho okufanele akuthole futhi.","also":["izindlela zesikhashana","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"Iphutha elaziwayo","text":"Inkinga eyaziwa imbangela yayo kodwa engakalungiswa, imvamisa ibhalwe nendlela yesikhashana. I-🧩 Known errors iyazibala, ukuze wonke umuntu asebenzise indlela yesikhashana esikhundleni sokumba futhi.","also":["amaphutha aziwayo","known error","known errors"]},{"id":"runbook","g":"run","word":"I-runbook","text":"Imiyalelo yesinyathelo ngesinyathelo yokulungisa uhlobo lwenkinga olwaziwayo, ukuze kwenziwe ngendlela efanayo, ngokushesha, njalo. Ngemva kwesigameko esikhulu ithimba lingaphakamisa i-runbook ukuze uyivume.","also":["runbook","runbooks","ama-runbook"]},{"id":"ci","g":"run","word":"Into yokulungiselela","text":"Into eyodwa isevisi yakho encike kuyo, njengeseva, isizinda, isitifiketi, ukhiye noma umhlinzeki. 🗂️ Izinto izibala ngesevisi ngayinye, ukuze ubone ukuthi isigameko sithinta ini nokuthi yini edinga ukuvuselelwa noma isipele.","also":["izinto zokulungiselela","izinto","configuration item","configuration items"]},{"id":"expiry","g":"run","word":"Usuku lokuphelelwa yisikhathi","text":"Usuku into eyeka ukusebenza ngalo ngaphandle kokuba ivuselelwe, njengesitifiketi sokuphepha sewebhusayithi noma ikheli layo lewebhu. I-AI-gile ibheka lezi zinsuku yenze ikhadi elilodwa lokuvuselela ngalinye ezinsukwini ezingu-30 ngaphambili, ukuze kungabikho okuphela ngokungalindelekile.","also":["izinsuku zokuphelelwa yisikhathi","ukuphelelwa yisikhathi","ukuqapha ukuphelelwa","expiry date","expiry dates","expiry"]},{"id":"backup","g":"run","word":"Isipele","text":"Ikhophi elondoloziwe yedatha yakho yangaphambilini, ongabuyela kuyo uma okuthile kulahlekile noma konakele. I-AI-gile yenza isipele samabhodi akho nsuku zonke.","also":["izipele","i-backup","backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Ukubuyisela","text":"Ukubuyisa idatha isuka esipeleni. Isipele sibaluleke ngempela kuphela uma wazi ukuthi singabuyiselwa, ngakho kufanele ukuzama ngezikhathi ezithile.","also":["buyisela","kubuyiselwe","restore","restored"]},{"id":"svcreview","g":"run","word":"Ukubuyekezwa kwesevisi","text":"Ukubheka emuva enyangeni eyodwa yesevisi: izigameko ezivuliwe nezilungisiwe, ukuthi abantu bathole impendulo ngokushesha kangakanani, isikhathi sokusebenza nama-token asetshenzisiwe. Ukubuyekezwa kwenyanga kukukhombisa lokhu kusevisi ngayinye.","also":["ukubuyekezwa kwamasevisi","ukubuyekezwa kwenyanga","service review","monthly review"]},{"id":"accessreview","g":"run","word":"Ukubuyekezwa kokufinyelela","text":"Ukuhlola njalo ezinsukwini ezingu-90 ukuthi ngubani osenelungelo lokungena: izixhumanisi zokwabelana, izindima zabangani namaphasiwedi nokhiye abagciniwe. Ugcina noma ususe ngamunye, ukuze ukufinyelela okudala kungahlali.","also":["ukubuyekezwa kokufinyelela","access review","access reviews"]},{"id":"improvements","g":"run","word":"Uhlu lokuthuthukiswa","text":"Konke ithimba elinqume ukukwenza kangcono, endaweni eyodwa: iziphakamiso ze-retro, izenzo zokubuyekeza nokulungiswa kwezinkinga, ngakunye nesimo sakhona. Kuthole ngaphansi kwe-📈 Ukuthuthukiswa.","also":["uhlu lokuthuthukiswa","ukuthuthukiswa","improvement list","improvements"]},{"id":"tokencap","g":"run","word":"Umkhawulo wama-token","text":"Umkhawulo wenyanga wama-token izikhulumeli zesevisi ezingawasebenzisa. Ku-80% uthola isexwayiso; ku-100% umsebenzi wazo wangemuva ulinda kuze kube yinyanga ezayo noma uze ukhuphule umkhawulo.","also":["imikhawulo yama-token","umkhawulo wama-token wenyanga","token cap","token caps"]},{"id":"svcmgmt","g":"run","word":"Ukuphatha isevisi (Service management)","text":"Konke okubandakanyekayo ekugcineni isevisi iwusizo futhi isebenza kulabo abayethembele kuyo, usuku nosuku.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Umhlahlandlela osetshenziswa kakhulu wokuphatha amasevisi kahle, ohlanganisa izinto ezinjengezigameko, izinkinga nezinguquko. Igama lalo lalimele i-IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Ukuphatha amasevisi e-IT (ITSM)","text":"Ukuphatha ubuchwepheshe njengesevisi yabantu, ngezindlela ezicacile zokuphatha izicelo, izigameko, izinguquko nokuthuthukisa.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Isevisi ephethwe (Managed service)","text":"Isevisi omunye umuntu ayiphethe futhi ayinakekela esikhundleni sakho, ngaphansi kwesivumelwano sokuthi kufanele isebenze kahle kangakanani.","also":["managed service","managed services","amasevisi aphethwe"]},{"id":"svcowner","g":"run","word":"Umnikazi wesevisi (Service owner)","text":"Umuntu ophendulela isevisi iyonke: ukuthi isebenza kahle kangakanani, ibiza malini nokuthi ithuthuka kanjani.","also":["abanikazi besevisi","service owner","service owners"]},{"id":"sla","g":"run","word":"Isivumelwano sezinga lesevisi (SLA)","text":"Isethembiso esibhaliwe samaklayenti sokuthi isevisi izosebenza kahle kangakanani, njengokuthi “iphila ngo-99.9% wesikhathi” noma “iphendulwe ngaphakathi kwehora”, imvamisa nemali ebuyiswayo uma kuphukile.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Inhloso yezinga lesevisi (SLO)","text":"Okuhlosiwe okungokweqembu mayelana nokuthi isevisi kufanele isebenze kahle kangakanani esikhathini, imvamisa kubekwa kuqine kancane kune-SLA ukuze kuphepheke.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Isikhombi sezinga lesevisi (SLI)","text":"Isilinganiso sangempela osihlola kuqhathaniswa nenhloso, njengengxenye yokuvakasha okulayishe kahle.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Ukutholakala (Availability)","text":"Ukuthi abantu bangayisebenzisa yini isevisi uma beyidinga, okuvame ukulinganiswa nge-uptime.","also":["high availability","availability"]},{"id":"downtime","g":"run","word":"Isikhathi sokungasebenzi (Downtime)","text":"Isikhathi lapho isevisi ingasebenzi noma ivaliwe, kuhleliwe noma kungahlelwanga.","also":["down time","downtime"]},{"id":"errorbudget","g":"run","word":"Isabelomali samaphutha (Error budget)","text":"Inani elincane lokwehluleka umgomo wakho wokwethembeka olivumelayo. Uma kusasele, ungathatha amathuba ngezinguquko; uma seliphelile, wehlisa ijubane.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Ukuphuka kwesevisi (Outage)","text":"Isikhathi lapho isevisi ingasebenzi noma iphuke kakhulu kubasebenzisi bayo.","also":["outage","outages"]},{"id":"degraded","g":"run","word":"Ayisebenzi kahle (Degraded)","text":"Iyasebenza, kodwa kabi: ihamba kancane, noma ezinye izingxenye zayo azisebenzi.","also":["degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Ukuqapha (Monitoring)","text":"Ukubuka isevisi ngokuzenzakalelayo ngaso sonke isikhathi, ukuze izinkinga zibonwe, kungcono ngaphambi kokuba abasebenzisi bazibone.","also":["monitoring"]},{"id":"observability","g":"run","word":"Ukubonakala kwesistimu (Observability)","text":"Ukuthi ukwazi kahle kangakanani ukusho ukuthi kwenzekani ngaphakathi kwesistimu usuka ngaphandle, usebenzisa amalogi ayo, izinombolo namathrekhi.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Ilogi (Log)","text":"Idayari eqhubekayo uhlelo oluyigcinayo yalokho olwenzayo, esetshenziselwa ukuthola ukuthi yini engahambanga kahle.","also":["amalogi","log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Ithrekhi (Trace)","text":"Irekhodi lokuthi isicelo esisodwa sihamba kanjani phakathi kwezingxenye ezihlukene zesistimu, isinyathelo ngesinyathelo, kukhombisa lapho sehlise isivinini khona.","also":["amathrekhi","trace","traces","tracing"]},{"id":"latency","g":"run","word":"Ukubambezeleka kwempendulo (Latency)","text":"Isikhathi esithathwa okuthile ukuphendula, njengokulinda phakathi kokuqhafaza nokuvela kwekhasi.","also":["latency"]},{"id":"alert","g":"run","word":"Isexwayiso (Alert)","text":"Umlayezo ozenzakalelayo othi okuthile kudinga ukunakwa, njengewebhusayithi engaphenduli.","also":["izexwayiso","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Ukukhathala ngezexwayiso (Alert fatigue)","text":"Uma izexwayiso zingaka kangangokuba abantu baqala ukuzishaya indiva, kuhlanganise nezibalulekile.","also":["alarm fatigue","alert fatigue"]},{"id":"dashboard","g":"run","word":"Ideshibhodi (Dashboard)","text":"Isikrini esibonisa izinombolo nezimo ezibaluleke kakhulu ngokuphazima kweso.","also":["amadeshibhodi","dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Ukubiza okuphuthumayo (Paging)","text":"Ukubiza noma ukuvusa ngokuphuthuma umuntu olindile (on-call) ngenxa yenkinga.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Ukudlulisela phezulu (Escalation)","text":"Ukulethwa komuntu onamakhono amaningi noma igunya elikhulu uma udaba lungaxazululeki ezingeni lamanje, noma lungaxazululeki ngokushesha okwanele.","also":["escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Ukuhlunga kokuqala (Triage)","text":"Ukuhlunga ngokushesha izinkinga ezifikayo ngokuthi zisheshe futhi zibaluleke kangakanani, ukuze ezimbi kakhulu zinakekelwe kuqala.","also":["triage","triaged"]},{"id":"impact","g":"run","word":"Umthelela (Impact)","text":"Ukuthi into ithinta abantu kangakanani: abangaki, nokuthi kubi kangakanani.","noTip":1},{"id":"urgency","g":"run","word":"Ukuphuthuma (Urgency)","text":"Ukuthi into idinga ukunakwa ngokushesha kangakanani. Umthelela nokuphuthuma ndawonye kunquma okubekwa phambili.","noTip":1},{"id":"plevels","g":"run","word":"Amazinga okubekwa phambili (P1, P2…)","text":"Amalebuli okuthi udaba luphuthuma kangakanani. I-P1 iyona ebucayi kakhulu futhi idinga isenzo ngokushesha.","also":["P1","P2","P3","P4","Priority levels"]},{"id":"queue","g":"run","word":"Ulayini wama-ticket (Ticket queue)","text":"Uhlu lwezicelo nezigameko ezilindele ukuthathwa.","also":["ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Umugqa wokuqala nowesibili","text":"Amazinga osekelo: umugqa wokuqala uthatha ucingo futhi ulungisa izinto ezilula; owesibili unamakhono ajulile ezinto ezinzima. Kubizwa nangokuthi tier 1 ne-tier 2.","also":["first-line support","tier 1","tier 2","umugqa wokuqala","umugqa wesibili"]},{"id":"ic","g":"run","word":"Umholi wesigameko (Incident commander)","text":"Umuntu oyedwa oholela impendulo esigamekweni, ukuze wonke umuntu azi ukuthi ngubani onquma nokuthi ngubani owenzani.","also":["abaholi bezigameko","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Isikhathi sokuphendula (Response time)","text":"Isikhathi esithathwa ngaphambi kokuba othile athathe isicelo noma isigameko okokuqala.","also":["izikhathi zokuphendula","response time","response times"]},{"id":"resolution","g":"run","word":"Isikhathi sokuxazulula (Resolution time)","text":"Isikhathi esithathwa ukuxazulula ngokuphelele isicelo noma isigameko, kusukela ekubikweni kuze kulungiswe.","also":["izikhathi zokuxazulula","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Isikhathi esimaphakathi sokubuyisela (MTTR)","text":"Ngokwesilinganiso, isikhathi esithathwa ukuze isevisi isebenze futhi ngemva kokuphuka. I-MTTR ingasho izinto ezihlukile kancane, ngakho sho ukuthi ulinganisani.","also":["MTTR","mean time to restore","Mean time to recover"]},{"id":"mtbf","g":"run","word":"Isikhathi esimaphakathi phakathi kokwehluleka (MTBF)","text":"Ngokwesilinganiso, isikhathi isevisi esebenza ngaso ngaphambi kokuba okuthile kuphuke.","also":["MTBF","Mean time between failures"]},{"id":"cmdb","g":"run","word":"Isizindalwazi sokuphatha ukucushwa (CMDB)","text":"Uhlu lwazo zonke izinto zakho zokucushwa nokuthi zixhumana kanjani, ukuze ubone ukuthi yini encike kuphi.","also":["CMDB","Configuration management database"]},{"id":"asset","g":"run","word":"Impahla (Asset)","text":"Noma yini ebalulekile oyiphethe noma ukhokhela yona ukuze isevisi isebenze, njengelaptop, ilayisense yesofthiwe noma isizinda.","also":["izimpahla","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Ukuhlela umthamo (Capacity planning)","text":"Ukuqinisekisa ukuthi kuzoba namandla ekhompyutha, isitoreji nabantu abanele lokho okuzayo.","also":["capacity plan","capacity planning"]},{"id":"scaling","g":"run","word":"Ukukhulisa isistimu (Scaling)","text":"Ukumelana nabasebenzisi abaningi ngokunika umshini amandla amaningi (scaling up) noma ngokwengeza imishini eminingi (scaling out).","also":["scale up","scale out","scaling up","scaling out","scaling"]},{"id":"bcp","g":"run","word":"Ukuqhubeka kwebhizinisi (Business continuity)","text":"Izinhlelo zokugcina izinto ezibalulekile ziqhubeka uma okuthile okukhulu kungahambi kahle, njengokulahlekelwa yihhovisi, umhlinzeki obalulekile noma amakhompyutha.","also":["business continuity plan","business continuity"]},{"id":"dr","g":"run","word":"Ukubuyisela ngemva kwenhlekelele (DR)","text":"Uhlelo namathuluzi okubuyisa isevisi ngemva kokuthi kwenzeke okubi kakhulu, njengokulahlekelwa yisikhungo sedatha esiphelele.","also":["disaster recovery","DR"]},{"id":"rto","g":"run","word":"Inhloso yesikhathi sokubuyisa (RTO)","text":"Isikhathi eside kakhulu isevisi engahlala ingasebenzi ngemva kwenhlekelele ngaphambi kokuba kufanele isebenze futhi.","also":["RTO","Recovery time objective"]},{"id":"rpo","g":"run","word":"Inhloso yephoyinti lokubuyisa (RPO)","text":"Ukuthi ingakanani idatha yakamuva ongakwazi ukulahlekelwa yiyo, ekalwa ngesikhathi. I-RPO yehora elilodwa isho izipele okungenani njalo ngehora.","also":["RPO","Recovery point objective"]},{"id":"redundancy","g":"run","word":"I-Redundancy (izinto ezilindile)","text":"Ukuba nezinto ezilindile ezilungile, njengeseva yesibili, ukuze ukwehluleka okukodwa kungayimisi isevisi.","also":["redundancy","izinto ezilindile"]},{"id":"failover","g":"run","word":"Ukushintshela kokulindile (Failover)","text":"Ukushintshela ngokuzenzakalelayo kusistimu elindile uma ejwayelekile yehluleka.","also":["fail over","failover"]},{"id":"spof","g":"run","word":"Iphuzu elilodwa lokwehluleka (Single point of failure)","text":"Ingxenye eyodwa eyehlisa yonke into uma iphuka, ngoba akukho okulindile.","also":["single points of failure","SPOF","Single point of failure"]},{"id":"maintwin","g":"run","word":"Iwindi lokunakekela (Maintenance window)","text":"Isikhathi esihleliwe lapho isevisi ingamiswa noma ihambe kancane ukuze inakekelwe, imenyezelwe kubasebenzisi kusengaphambili.","also":["maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Ukudlulisela (Handover)","text":"Ukudlulisela umsebenzi, ulwazi nomthwalo kumunye umuntu noma iqembu, ukuze kungalahleki lutho.","also":["handovers","handover"]},{"id":"kb","g":"run","word":"Umtapo wolwazi (Knowledge base)","text":"Iqoqo lezihloko zosizo nezimpendulo, zabasebenzisi neqembu.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Injabulo yamakhasimende (CSAT)","text":"Amaphuzu avela kubasebenzisi abonisa ukuthi bajabule kangakanani, avame ukucelwa ngemva kokuvalwa kwesicelo.","also":["CSAT","Customer satisfaction"]},{"id":"supplier","g":"run","word":"Umhlinzeki (Supplier)","text":"Inkampani yangaphandle oyethembele kuyo, njengomhlinzeki wakho we-hosting. Ibizwa nangokuthi vendor noma third party.","also":["abahlinzeki","supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Ukuhoxisa isevisi (Service retirement)","text":"Ukuvala isevisi unomphela, ngokuphepha: ukwazisa abasebenzisi bayo, ukuphatha idatha nokufinyelela kwayo, nokuqeda izindleko zayo.","also":["retiring a service","service retirement"]},{"id":"eol","g":"run","word":"Ukuphela kwempilo yomkhiqizo (EOL)","text":"Uma umkhiqizo uyeka ukuthola izibuyekezo noma usekelo kumkhiqizi wawo, ngakho kufanele ushintshwe.","also":["EOL","end-of-life","End of life"]},{"id":"cybersec","g":"sec","word":"Ukuphepha kwe-inthanethi (Cybersecurity)","text":"Ukuvikela izistimu nedatha ekuphulweni, ekutshontshweni noma ekonakalisweni.","also":["cyber security","cybersecurity"]},{"id":"authn","g":"sec","word":"Ukuqinisekisa ubuqiniso (Authentication)","text":"Ukuhlola ukuthi umuntu ungubani, imvamisa ngephasiwedi noma ikhodi. Kuvame ukufushaniswa kube i-authn.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Ukugunyaza (Authorisation)","text":"Ukuhlola ukuthi umuntu uvunyelwe ukwenzani uma usuyazi ukuthi ungubani. Kuvame ukufushaniswa kube i-authz.","also":["authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Ukuqinisekisa ngezigaba eziningi (MFA)","text":"Ukungena ngobufakazi obubili noma ngaphezulu, njengephasiwedi nekhodi ocingweni lwakho. Kubizwa nangokuthi two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","Multi-factor authentication"]},{"id":"sso","g":"sec","word":"Ukungena kanye (SSO)","text":"Ukungena kanye ukuze ungene ezistimini eziningi, njengokusebenzisa i-akhawunti yakho yomsebenzi yonke indawo.","also":["SSO","Single sign-on"]},{"id":"pwmgr","g":"sec","word":"Umphathi wamaphasiwedi (Password manager)","text":"I-app edala amaphasiwedi aqinile futhi ikukhumbulele wona.","also":["abaphathi bamaphasiwedi","password manager","password managers"]},{"id":"secret","g":"sec","word":"Imfihlo (Secret)","text":"Iphasiwedi, ukhiye noma enye ikhodi yangasese uhlelo olisebenzisayo ukungena kokuthile. Akumele kwabelwane ngayo noma kubhalwe ekhodini.","also":["izimfihlo","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Ukhiye we-API (API key)","text":"Ikhodi yangasese evumela uhlelo ukuthi lisebenzise i-API yenye isevisi, futhi ikhombisa ukuthi ngubani oyisebenzisayo (nokhokhelayo).","also":["okhiye be-API","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Ithokheni yokufinyelela (Access token)","text":"Ipasi lesikhashana eliqinisekisa ukuthi uhlelo luvunyelwe ukungena, ukuze lungadingi iphasiwedi yakho njalo. Alifani ne-AI token.","also":["amathokheni okufinyelela","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Ukubhala ngekhodi (Encryption)","text":"Ukuxubanisa ulwazi ukuze umuntu onokhiye ofanele kuphela akwazi ukulufunda.","also":["encrypted","encrypt","encryption"]},{"id":"https","g":"sec","word":"HTTPS","text":"Indlela evikelekile amakhasi ewebhu ahamba ngayo, ekhonjiswa yisikhiya kusiphequluli sakho, ukuze kungabikho ophakathi ongawafunda noma awashintshe."},{"id":"cert","g":"sec","word":"Isitifiketi se-SSL/TLS","text":"Ikhadi le-ID lamadijithali eliyivumela iwebhusayithi ukuthi ifakazele ukuthi iyini futhi isebenzise i-HTTPS. Liyaphelelwa isikhathi, ngakho kumele livuselelwe.","also":["TLS certificate","SSL certificate","certificate","certificates","isitifiketi"]},{"id":"permissions","g":"sec","word":"Izimvume (Permissions)","text":"Imithetho yokuthi ngubani ongabona noma ashintshe ini.","also":["izimvume","permission","permissions"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Amalungelo aphansi kakhulu (Least privilege)","text":"Ukunika umuntu ngamunye noma uhlelo ngalunye ukufinyelela okudingayo ngempela kuphela, isikhathi esidingayo kuphela.","also":["principle of least privilege","least privilege"]},{"id":"rbac","g":"sec","word":"Ukulawula ukufinyelela ngendima (RBAC)","text":"Ukunikeza ukufinyelela ngendima, njengobukayo noma ohlelayo, esikhundleni somuntu ngamunye.","also":["RBAC","role-based access","Role-based access control"]},{"id":"vuln","g":"sec","word":"Ubuthakathaka (Vulnerability)","text":"Indawo ebuthakathaka umuntu angayisebenzisa ukuze angene noma alimaze.","also":["vulnerability","vulnerabilities","ubuthakathaka"]},{"id":"zeroday","g":"sec","word":"I-Zero-day","text":"Ubuthakathaka abahlaseli abazi ngabo ngaphambi kokuba abenzi babe nesikhathi sokubulungisa.","also":["zero-day","zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Isofthiwe eyingozi, njengamawayirasi, eyenzelwe ukulimaza, ukuqamekela noma ukutshontsha.","also":["isofthiwe eyingozi"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"I-malware evala amafayela akho futhi icela imali ukuze iwavule. Izipele ezinhle yizona ezikuvikela kangcono.","also":["ransomware attack","ukuhlasela kwe-ransomware"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Imilayezo yamanga ezama ukukukhohlisa ukuze unikeze amaphasiwedi noma imali, noma uvule okuyingozi.","also":["phishing email","phishing emails","phishing"]},{"id":"socialeng","g":"sec","word":"Ukukhohlisa abantu (Social engineering)","text":"Ukukhohlisa abantu, hhayi amakhompyutha, ukuze banikeze ukufinyelela, njengocingo lwamanga oluvela “ekusekelweni kwe-IT”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Umqaphi onquma ukuthi iyiphi ithrafikhi yenethiwekhi evunyelwe ukungena noma ukuphuma.","also":["ama-firewall","firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Isifinyezo se-virtual private network: isixhumo sangasese esifihliwe nge-inthanethi, esivame ukusetshenziselwa ukufinyelela ezinhlelweni zomsebenzi ngokuphepha.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Ukuvimba isevisi (DoS, DDoS)","text":"Ukukhukhula isevisi ngethrafikhi eningi yamanga kangangokuba abantu bangempela bangakwazi ukuyisebenzisa. I-DDoS isho ukuthi iphuma emakhompyutheni amaningi ngesikhathi esisodwa.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Ukuhlola ukungena (Pen test)","text":"Ukuqasha ochwepheshe abanobungane ukuthi bazame ukungena, ukuze ubuthakathaka butholwe ngaphambi kokuba abahlaseli bangempela babuthole.","also":["pen test","pen testing","penetration testing","pentest","Penetration test"]},{"id":"audit","g":"sec","word":"Ukucwaninga ukuphepha (Security audit)","text":"Ukuhlola ngokucophelela ukuthi into ivikelwe kahle kangakanani, kuqhathaniswa nohlu lwemikhuba emihle.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Ukuhlela izinsongo (Threat modelling)","text":"Ukucabanga ngokuthi ngubani ongahlasela into, kanjani, nokuthi ungenzani ukubavimba.","also":["threat model","threat modeling","threat modelling"]},{"id":"breach","g":"sec","word":"Ukuvuza kwedatha (Data breach)","text":"Uma ulwazi lwangasese lufika kubantu okungafanele balube nalo, noma lulahleka noma lushintshwa ngaphandle kwemvume.","also":["data breach","data breaches"]},{"id":"pii","g":"sec","word":"Idatha yomuntu siqu (Personal data)","text":"Noma yimuphi ulwazi ngomuntu ongahlonzwa, njengegama, ikheli le-imeyili noma indawo. Lubizwa nangokuthi PII.","also":["PII","personally identifiable information","personal data"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Umthetho waseYurophu wedatha yomuntu siqu (i-UK inenguqulo yayo): qoqa kuphela okudingayo, kugcine kuphephile, futhi wenze abantu bakwazi ukubona noma ukusula eyabo.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Ukuvikela idatha (Data protection)","text":"Ukunakekela idatha yomuntu siqu ngokufanele nangaphakathi komthetho.","also":["data protection law","data protection"]},{"id":"privacypolicy","g":"sec","word":"Inqubomgomo yobumfihlo (Privacy policy)","text":"Ikhasi elisesidlangalaleni elithi yiluphi ulwazi lomuntu siqu oluqoqayo, kungani, nokuthi ulwenzani.","also":["privacy statement","privacy notice","privacy policy"]},{"id":"consent","g":"sec","word":"Imvume (Consent)","text":"Impendulo yebo ecacile nekhululekile yomuntu yokuthi idatha yakhe isetshenziswe ngendlela ethile. Angayibuyisa noma nini.","also":["opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Ikhukhi (Cookie)","text":"Ifayela elincane iwebhusayithi eyigcina kusiphequluli sakho ukuze ikhumbule izinto, njengokuthi ungenile. Amanye adinga imvume yakho kuqala.","also":["amakhukhi","cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Ukunciphisa idatha (Data minimisation)","text":"Ukuqoqa nokugcina kuphela idatha yomuntu siqu oyidinga ngempela emsebenzini.","also":["data minimization","data minimisation"]},{"id":"retention","g":"sec","word":"Ukugcinwa kwedatha (Data retention)","text":"Ukuthi idatha igcinwa isikhathi esingakanani ngaphambi kokuba isulwe. Ukungayigcini ngaphezu kokudingekile kuphephile kakhulu futhi kuvame ukuba ngumthetho.","also":["retention period","data retention"]},{"id":"anon","g":"sec","word":"Ukwenza idatha ingaziwa (Anonymisation)","text":"Ukushintsha idatha ukuze kungabikho umuntu ongaphinda ahlonzwe ngayo ngendlela enengqondo.","also":["anonymised","anonymization","anonymous data","anonymisation"]},{"id":"pseudo","g":"sec","word":"Ukufihla amagama (Pseudonymisation)","text":"Ukushintshanisa amagama neminye imininingwane ngamakhodi, nokhiye ogcinwe ngokwehlukile wokuwaxhumanisa futhi. Kodwa isabalwa njengedatha yomuntu siqu.","also":["pseudonymised","pseudonymization","pseudonymisation"]},{"id":"dpa","g":"sec","word":"Isivumelwano sokucubungula idatha (DPA)","text":"Inkontileka ethi umhlinzeki angayiphatha kanjani idatha yomuntu siqu egameni lakho.","also":["DPA","Data processing agreement"]},{"id":"dpia","g":"sec","word":"Ukuhlolwa komthelela wokuvikela idatha (DPIA)","text":"Ukubheka ngokucophelela, ngaphambi kokuqala, ukuthi uhlelo lokusebenzisa idatha yomuntu siqu lungathinta kanjani abantu nokuthi ungabehlisa kanjani ubungozi.","also":["DPIA","Data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Ilogi yokucwaninga (Audit log)","text":"Irekhodi lokuthi ngubani owenzeni nini, ukuze izenzo zihlolwe kamuva.","also":["audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Ukuhambisana nemithetho (Compliance)","text":"Ukulandela imithetho, imithethonqubo namazinga akusebenzelayo, nokukwazi ukukhombisa ukuthi uyakwenza.","also":["compliant","compliance"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Izinga lamazwe ngamazwe elaziwa kakhulu lokuphatha ukuphepha kolwazi. Izinkampani zingaqinisekiswa ngalo.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Umbiko wase-US, ohlolwe ngabahloli bangaphandle, okhombisa ukuthi inkampani inakekela kahle idatha yamakhasimende.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"I-AI esebenza emsebenzini yodwa: ifunda ikhodi, yenza izinguquko, iqhuba ukuhlola, ibike emuva. Umsebenzi wayo usahlolwa nokho.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Izingcezu ezincane zombhalo i-AI ezifundayo nezibhalayo, cishe izingxenye ezintathu kwezine zegama ngayinye. Ukusetshenziswa kwe-AI kubalwa ngama-token, ngakho ama-token ambalwa ashiya okuningi kohlelo lwakho.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Umyalo omncane osebenza wodwa ngesikhathi esimisiwe, isibonelo uma iseshini ye-AI iqala, ukuze iqembu lizwe amakhomenti akho.","also":["hooks"]},{"id":"ai","g":"ai","word":"Ubuhlakani bokwenziwa (AI)","text":"Izistimu zekhompyutha ezenza izinto esivame ukucabanga ukuthi zidinga umuntu, njengokubhala, ukuphendula imibuzo noma ukubona izithombe.","also":["AI","artificial intelligence","ubuhlakani bokwenziwa"],"noTip":1},{"id":"ml","g":"ai","word":"Ukufunda komshini (ML)","text":"Indlela yokwenza amakhompyutha afunde amaphethini ezibonelweni eziningi, esikhundleni sokuwanika imithetho eqondile.","also":["machine learning","ML","ukufunda komshini"]},{"id":"model","g":"ai","word":"Imodeli (Model)","text":"“Ubuchopho” obuqeqeshiwe bohlelo lwe-AI, obakhiwe ngokufunda ezibonelweni eziningi kakhulu. Amamodeli ahlukile ekhonweni, ekushesheni nasentengo.","also":["amamodeli","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Imodeli enkulu yolimi (LLM)","text":"Imodeli ye-AI eqeqeshwe ngombhalo omningi kakhulu, ukuze ikwazi ukufunda nokubhala ulimi.","also":["LLM","LLMs","Large language model"]},{"id":"genai","g":"ai","word":"I-AI ekhiqizayo (Generative AI)","text":"I-AI edala izinto ezintsha, njengombhalo, izithombe noma ikhodi, esikhundleni sokuhlunga noma ukubona kuphela.","also":["GenAI","Generative AI"]},{"id":"chatbot","g":"ai","word":"Isixoxi (Chatbot)","text":"Uhlelo oxoxa nalo ngolimi lwansuku zonke, ngokuthayipha noma ngokukhuluma.","also":["amachatbot","chatbot","chatbots"]},{"id":"prompt","g":"ai","word":"I-Prompt","text":"Lokho okunika i-AI: umbuzo wakho noma iziqondiso, kanye nanoma yini oyinikayo. Ama-prompt acacile ngokuvamile athola izimpendulo ezingcono.","also":["ama-prompt","prompt","prompts"]},{"id":"prompteng","g":"ai","word":"Ubunjiniyela be-prompt (Prompt engineering)","text":"Ikhono lokubhala ama-prompt athola imiphumela ethembekile newusizo.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"I-prompt yesistimu (System prompt)","text":"Iziqondiso zangemuva i-AI ezithola ngaphambi kokuba ingxoxo iqale, zibeka indima nemithetho yayo. Zinesisindo esikhulu kunalokho okuthayiphayo.","also":["system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Umongo (Context)","text":"Konke i-AI engakubona ngenkathi isebenza: iziqondiso, imilayezo yakho, amafayela ewafundile nezimpendulo zangaphambilini.","noTip":1},{"id":"ctxwin","g":"ai","word":"Iwindi lomongo (Context window)","text":"Ukuthi i-AI ingagcina kangakanani engqondweni ngesikhathi esisodwa, okulinganiswa ngama-token. Uma kudlulwa lapho, izingxenye ezindala ziyalahlwa noma zifinyezwe.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"Iseshini (Session)","text":"Ingxoxo eyodwa yomsebenzi ne-AI, kusukela ekuqaleni kuze kube sekugcineni. Iseshini entsha iqala ngenkumbulo entsha.","also":["amaseshini","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Inkumbulo (Memory)","text":"Amanothi i-AI iwagcina phakathi kwamaseshini, ukuze ikhumbule okuthandayo nezinqumo zangaphambilini.","noTip":1},{"id":"hallucination","g":"ai","word":"Ukuqamba amanga (Hallucination)","text":"Uma i-AI isho okuthile okuzwakala kuqinisekile kodwa kuqanjiwe noma kungalungile. Hlola amaqiniso abalulekile.","also":["hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Ukuqeqeshwa (Training)","text":"Ukufundisa imodeli ngokuyikhombisa izibonelo eziningi kakhulu, ngaphambi kokuba muntu ayisebenzise.","also":["trained","training"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Idatha yokuqeqesha (Training data)","text":"Izibonelo imodeli efunde kuzo. Ulwazi lwayo luphela ngosuku leyo datha eyaqoqwa ngalo.","also":["training set","training data"]},{"id":"cutoff","g":"ai","word":"Usuku lokugcina lolwazi (Knowledge cutoff)","text":"Usuku ulwazi olwakhelwe ku-AI oluphela ngalo. Ngeke yazi ngezinto zakamuva ngaphandle kokuthi izifunde ngokusesha.","also":["training cutoff","knowledge cutoff"]},{"id":"finetune","g":"ai","word":"Ukucija imodeli (Fine-tuning)","text":"Ukuqeqeshwa okwengeziwe kwemodeli ekhona ngezibonelo zakho, ukuze ibe ngcono emsebenzini oyedwa othile.","also":["fine-tune","fine-tuned","fine tuning","fine-tuning"]},{"id":"inference","g":"ai","word":"Ukusebenzisa imodeli (Inference)","text":"Imodeli ye-AI ngenkathi isetshenziswa ngempela ukuphendula okuthile, ngokungafani nenkathi iqeqeshwa.","also":["model inference","inference"]},{"id":"tooluse","g":"ai","word":"Ukusebenzisa amathuluzi (Tool use)","text":"I-AI ikwazi ukwenza izinto, hhayi ukukhuluma kuphela: ukusebenzisa imiyalo, ukufunda amafayela noma ukusesha iwebhu, ngamathuluzi i-app iyinika wona.","also":["tool calling","tool call","tool calls","tool use"]},{"id":"subagent","g":"ai","word":"Umsizi we-agent (Subagent)","text":"I-AI esizayo leyo i-AI eyinhloko eyinika umsebenzi omncane, bese ithola umphumela kuyo.","also":["subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Ama-agent amaningi (Multi-agent)","text":"Ama-AI amaningana asebenza ndawonye kucezu lomsebenzi olulodwa, ngalinye linengxenye yalo, njengeqembu elincane.","also":["multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Ukuzimela (Autonomy)","text":"Ukuthi i-AI ingenza kangakanani yodwa ngaphambi kokuthi ibuze umuntu.","also":["autonomous","autonomy"]},{"id":"hitl","g":"ai","word":"Umuntu osenqubweni (Human in the loop)","text":"Ukugcina umuntu ebandakanyekile ukuhlola noma ukuvuma lokho i-AI ekwenzayo emaphuzwini abalulekile. Ku-AI-gile yiwena lowo.","also":["human-in-the-loop","HITL","Human in the loop"]},{"id":"guardrails","g":"ai","word":"Izivimbelo zokuphepha (Guardrails)","text":"Imikhawulo nokuhlolwa okugcina izenzo ze-AI ziphephile, njengokudinga imvume ngaphambi kokuba kuphile okuthile. Kunciphisa ubungozi bamaphutha, kodwa akubususi ngokuphelele.","also":["guardrail","guardrails"]},{"id":"rag","g":"ai","word":"Ukukhiqiza okuthuthukiswa ukutholwa kolwazi (RAG)","text":"Ukuvumela i-AI ukuthi ibheke izinto emibhalweni yakho ngaphambi kokuphendula, ukuze izimpendulo zayo zisekelwe emaqinisweni akho.","also":["RAG","retrieval augmented generation","Retrieval-augmented generation"]},{"id":"embedding","g":"ai","word":"I-Embedding","text":"Ukuguqula umbhalo ube uhlu lwezinombolo olubamba incazelo yawo, ukuze ikhompyutha ithole izinto ezisho into efanayo.","also":["embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Isizindalwazi se-vector (Vector database)","text":"Isizindalwazi esakhelwe ukusesha lolo hlu lwezinombolo (ama-embedding), ukuthola izinto ezinencazelo efanayo.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Indlela evamile yokuxhuma amathuluzi nemithombo yedatha kuma-app e-AI, ukuze i-AI ikwazi ukuwasebenzisa.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Izinga lokushisa (Temperature)","text":"Isilungiselelo sokuthi izimpendulo ze-AI zehlukahluka kangakanani. Ephansi inika izimpendulo ezizinzile nezibikezelekayo; ephezulu inika ezehlukahlukene kakhulu. Akukho neyodwa eyenza ihlale ilungile.","also":["model temperature","temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Ikwazi ukusebenza ngohlobo olungaphezu koluyedwa lolwazi, njengombhalo, izithombe nomsindo.","also":["multi-modal","multimodal"]},{"id":"evals","g":"ai","word":"Ukuhlolwa kwe-AI (Evaluation, eval)","text":"Ukuhlola okuhleliwe ukuthi i-AI isebenza kahle kangakanani ezibonelweni ezikhethiwe, ukuze uqhathanise amamodeli noma ama-prompt.","also":["eval","evals","Evaluation"]},{"id":"bias","g":"ai","word":"Ukuthambekela (Bias)","text":"Uma i-AI (noma umuntu) ithambekela ngokungafanele ohlangothini olulodwa, imvamisa ngenxa yalokho ekufunde kukho.","also":["biased","bias","ukuthambekela"],"noTip":1},{"id":"responsible","g":"ai","word":"I-AI enesibopho (Responsible AI)","text":"Ukusebenzisa i-AI ngobulungiswa, ngokuphepha nangokwethembeka, abantu besaphendula ngemiphumela.","also":["ethical AI","responsible AI","i-AI enesimilo"]},{"id":"injection","g":"ai","word":"Ukufaka iziqondiso ezifihliwe (Prompt injection)","text":"Ubuqili lapho iziqondiso ezifihliwe ekhasini lewebhu noma efayelini zizama ukwenza i-AI yenze into umsebenzisi wayo angayicelanga.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Umkhawulo wezicelo (Rate limit)","text":"Umkhawulo wokuthi mangaki izicelo ongazithumela enkonzweni esikhathini esimisiwe. Uma udlula kuwo, kumele ulinde.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Umkhawulo wokusetshenziswa (Usage limit)","text":"Ukuthi umsebenzi we-AI omningi kangakanani uhlelo lwakho oluwuvumelayo esikhathini, ngemva kwalokho uyama noma ubiza kakhulu.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Ukwakha isofthiwe ikakhulukazi ngokuchaza ofuna ku-AI bese uyivumela ibhale ikhodi.","also":["vibe-coding","vibe coding"]},{"id":"budget","g":"money","word":"Isabelomali (Budget)","text":"Inani lemali elibekelwe into.","also":["izabelomali","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Isilinganiselo sezindleko (Cost estimate)","text":"Ukuqagela okuhle kakhulu kokuthi into izobiza malini ngaphambi kokuba uqale.","also":["izilinganiselo zezindleko","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Inzuzo ekutshalweni kwemali (ROI)","text":"Lokho okubuyelayo uma kuqhathaniswa nalokho okufakile. Uma kunenzuzo, bekufanelekile.","also":["ROI","Return on investment"]},{"id":"tco","g":"money","word":"Izindleko eziphelele zobunikazi (TCO)","text":"Konke okubizwa yinto ngempela empilweni yayo yonke, hhayi nje intengo yokuyithenga: ukuyisebenzisa, ukuyisekela, ukuyithuthukisa nokugcina ukuyisusa ekusebenzeni.","also":["TCO","Total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx ne-OpEx","text":"I-CapEx imali echithwa kusengaphambili ezintweni ozigcinayo; i-OpEx ukuchitha okuqhubekayo, njengamabhili ngenyanga.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Inkokhelo eqhubekayo (Subscription)","text":"Ukukhokha njalo, imvamisa ngenyanga noma ngonyaka, ukuze uqhubeke usebenzisa okuthile.","also":["izinkokhelo eziqhubekayo","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Isofthiwe njengesevisi (SaaS)","text":"Isofthiwe oyisebenzisa nge-inthanethi bese uyikhokhela ngenkokhelo eqhubekayo, kuyilapho umkhiqizi ekuphathela yona.","also":["SaaS","Software as a service"]},{"id":"payg","g":"money","word":"Khokha ngokusebenzisa (Pay as you go)","text":"Ukukhokhela kuphela lokho okusebenzisayo, njengamakhompyutha efu noma ama-token e-AI.","also":["pay-as-you-go","usage-based pricing","pay as you go"]},{"id":"overage","g":"money","word":"Ukusebenzisa ngokweqile (Overage)","text":"Ukusetshenziswa okungaphezu kwalokho uhlelo lwakho olukuhlanganisayo, okungabiza okwengeziwe.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Isexwayiso sebhili (Billing alert)","text":"Umlayezo uma ukuchitha noma ukusetshenziswa kufinyelela izinga olikhethile. Uyakuxwayisa, kodwa awuzimisi njalo izindleko ezengeziwe.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Izinga lamahhala (Free tier)","text":"Izinga lamahhala lesevisi ekhokhelwayo, elinemikhawulo. Lilusizo uma uqala.","also":["free plan","free tier"]},{"id":"pricing","g":"money","word":"Uhlelo lwamanani (Pricing plan)","text":"Amaphakheji ahlukene isevisi ewathengisayo, ngalinye linentengo yalo nemikhawulo yalo.","also":["pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Ilayisense (Licence)","text":"Imithetho yokuthi ungasebenzisa kanjani, ukopishe, ushintshe noma wabelane ngento eyenziwe ngomunye umuntu, njengesofthiwe, amafonti noma izithombe.","also":["amalayisense","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Umthombo ovulekile (Open source)","text":"Isofthiwe ikhodi yayo wonke umuntu angayifunda, ayisebenzise futhi imvamisa ayishintshe mahhala, ngaphansi kwemithetho yelayisense yayo.","also":["open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Ilayisense yomthombo ovulekile (Open source licence)","text":"Imithetho ehambisana nekhodi yomthombo ovulekile. Ezinye zikuvumela ukwenza cishe noma yini (njenge-MIT); ezinye zicela ukuthi wabelane ngezinguquko zakho nazo (njenge-GPL).","also":["open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Eyobunikazi (Proprietary)","text":"Ingeyenkampani futhi ayikhululekile ukukopishwa noma ukushintshwa. Okuphambene nomthombo ovulekile.","also":["proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Ilungelo lobunikazi (Copyright)","text":"Ilungelo elisemthethweni lomdali lokulawula amakhophi emisebenzi yakhe, kuhlanganise nekhodi nokubhaliwe.","also":["copyright","copyrighted","ilungelo lobunikazi"],"noTip":1},{"id":"ip","g":"money","word":"Impahla yengqondo (IP)","text":"Imibono nezidalwa umthetho ozibheka njengezinomnikazi, njengekhodi, imiklamo, amagama nama-logo.","also":["intellectual property","Intellectual property","IP"]},{"id":"tos","g":"money","word":"Imibandela yesevisi (Terms of service)","text":"Imithetho oyivumayo uma usebenzisa isevisi.","also":["terms and conditions","terms of use","terms of service"]},{"id":"contract","g":"money","word":"Inkontileka (Contract)","text":"Isivumelwano esibhaliwe phakathi kwezinhlangothi ezimbili umthetho ozosisekela.","also":["amakontileka","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Isitatimende somsebenzi (SOW)","text":"Idokhumenti ebeka ngqo ukuthi yimuphi umsebenzi ozokwenziwa, nini nangemali engakanani.","also":["SOW","Statement of work"]},{"id":"fixedprice","g":"money","word":"Intengo emisiwe (Fixed price)","text":"Intengo evunyelwene yawo wonke umsebenzi, noma uthatha isikhathi esingakanani.","also":["fixed-price","fixed price"]},{"id":"tm","g":"money","word":"Isikhathi nempahla (Time and materials)","text":"Ukukhokhela amahora asetshenzwe ngempela nezinto ezisetshenziswe ngempela, esikhundleni sentengo emisiwe.","also":["T&M","Time and materials"]},{"id":"invoice","g":"money","word":"I-invoyisi (Invoice)","text":"Ibhili elicela inkokhelo yomsebenzi owenziwe noma izimpahla ezinikeziwe.","also":["ama-invoyisi","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Ukubotshwa kumhlinzeki (Vendor lock-in)","text":"Uma ukusuka kumhlinzeki kunzima noma kubiza kangangokuba uzithola ubotshelwe kuye.","also":["lock-in","vendor lock-in"]},{"id":"procurement","g":"money","word":"Ukuthengwa kwezinsiza (Procurement)","text":"Inqubo yokukhetha nokuthenga kubahlinzeki.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Ikhredithi yesevisi (Service credit)","text":"Imali ebuyiswayo noma isaphulelo osithola uma umhlinzeki ehluleka ukufeza i-SLA yakhe.","also":["service credit","service credits"]}]}};
